// ShelfCheck curated dossier overrides — GameStop discovery integration batch (2026-11-09).
// Covers the 206 GameStop-discovered identities added by census-gamestop-nov-v001.js plus the
// 13 earlier additions that never received a dossier (Double Dragon Gaiden, Diablo IV, Demon Slayer
// Hinokami Chronicles, RayStorm, RayCrisis, Persona 5 Strikers, Riders Republic, Gungrave G.O.R.E.,
// Persona 5 Tactica, Babylon's Fall, Curse of the Sea Rats, Willy Morgan, OlliOlli2).
// Physical/coverage notes draw on audit-out/ALL_BATCHES_01-05_completed.csv evidence. Every entry
// passes tools/dossier-generate.mjs validate() rules and dossiers.js dossierQuality() as 'good'.
// Object-literal format; last-writer-wins via dossier-apply.js.
const DOSSIER_OVERRIDES_85 = [
{t:"Double Dragon Gaiden: Rise of the Dragons",s:"Secret Base's 2023 reimagining of Double Dragon as a tag-team beat 'em up with roguelite structure, where Billy, Jimmy, Marian and Uncle Matin clean up gang-run, post-apocalyptic New York in a mission order you choose.",w:"It is the most inventive modern take on the series: swapping between two fighters mid-combo, picking stage order to change difficulty, and buying permanent unlocks with earned tokens keeps short runs varied.",c:"Runs reset progress within a session, the token economy can feel grindy for unlocking the wider roster, and the chunky 16-bit art is deliberately busy in crowded fights.",r:"A strong fit for a shelf that values immediacy: quick to start, built around punchy two-player co-op, and short enough to replay with new character pairs without wearing out its welcome.",b:"Physical PS4 release from Modus Games, July 2023 (UPC 814290019037); the same disc also launched on Switch, Xbox and PS5.",p:"BUY cheap."},
{t:"Diablo IV",s:"Blizzard's 2023 action RPG returns Sanctuary to grim gothic horror as Lilith, Daughter of Hatred, is summoned back, with five classes, an open world split into regions, and loot-driven Nightmare Dungeon endgame.",w:"It is the PS4's last major Diablo release and a lavish one: strong art direction, satisfying class builds and couch co-op on a single console are all present on last-generation hardware.",c:"Always-online even in solo play, with a seasonal live-service structure and battle pass; the disc requires large updates, and the game will be less complete if servers are ever shut down.",r:"Worth owning for the campaign and couch co-op alone, but treat it as a service game: the story is the durable part, while the seasonal loot chase depends entirely on Blizzard's servers.",b:"Retail PS4 disc from Blizzard/Activision, June 2023; standard edition is the qualifying product, with online connection required to play.",p:"MAYBE cheap."},
{t:"Demon Slayer -Kimetsu no Yaiba- The Hinokami Chronicles",s:"CyberConnect2's 2021 anime adaptation retells Tanjiro Kamado's story from Final Selection through the Mugen Train arc as a cinematic action adventure, alongside a two-on-two arena versus mode.",w:"CyberConnect2 is the studio behind Naruto Ultimate Ninja Storm, and it brings the same spectacle here: story bosses reproduce the anime's biggest fights with lavish effects and faithful voice work.",c:"The story mode is short and linear, with light exploration between scripted battles; the versus fighting is accessible but shallow next to dedicated fighting games.",r:"A good fit for fans of the anime who want a polished, respectful retelling; less interesting for anyone looking for depth, since the fighting is mostly spectacle.",b:"Standalone physical PS4 release published in the West by Sega, October 2021; editions with bonus content are packaging of the same game.",p:"MAYBE cheap."},
{t:"RayStorm",s:"Taito's 1996 vertical shooter uses a lock-on laser that targets enemies on a lower plane, letting you sweep the cursor across fleets and release chained homing strikes for multiplied score.",w:"The lock-on system is the signature mechanic of Taito's Ray series and still feels distinct from bullet-hell design, rewarding planning and risk rather than pure dodging.",c:"Short arcade length, early polygonal visuals and score-attack focus mean it is best for players who enjoy replaying the same stages to improve.",r:"A concise, replayable arcade shooter that respects your time; the lock-on chaining gives every run a clear goal beyond survival.",b:"Qualifies through the physical PS4 RayStorm x RayCrisis HD Collection, which holds RayStorm and RayCrisis on one disc.",p:"BUY with RayCrisis collection."},
{t:"RayCrisis",s:"The 1998 prequel to RayStorm in Taito's Ray series, set inside a rogue AI's network, where an encroachment meter rises over time and the lock-on laser is the main tool for clearing it.",w:"RayCrisis adds a branching stage order and the time-pressure encroachment system, making it the most strategic of the Ray games while keeping the satisfying lock-on chains.",c:"Very short as a single run, and its abstract cyberspace stages are less visually striking than RayStorm's; it rewards score chasing more than casual play.",r:"Pairs naturally with RayStorm: a tight arcade design with a smart risk-and-reward twist that makes repeat runs worthwhile.",b:"Qualifies through the physical PS4 RayStorm x RayCrisis HD Collection, the same disc that carries RayStorm.",p:"BUY with RayStorm collection."},
{t:"Persona 5 Strikers",s:"Omega Force and Atlus's 2021 sequel to Persona 5 sends the Phantom Thieves on a summer road trip across Japan, replacing turn-based combat with real-time musou-style action built around Persona skills.",w:"It is a full canonical story sequel with the original cast and voice actors, and it carries the series' style, music and dungeon design into a faster action format.",c:"Combat leans on crowd fighting with a pause-to-cast skill menu; players expecting Persona's social sim and calendar structure will find those elements largely gone.",r:"A generous continuation for Persona 5 fans, with a 30-plus-hour story; it plays best as a victory lap with the Thieves rather than as a standalone entry point.",b:"Standalone physical PS4 release from Atlus and Sega, February 2021, sold as a standard disc alongside Switch.",p:"BUY cheap."},
{t:"Riders Republic",s:"Ubisoft Annecy's 2021 open-world extreme sports game combines bikes, skis, snowboards, wingsuits and rocket-wings across a compressed map of American national parks, with mass-start races of dozens of players.",w:"It is the PS4's most expansive outdoor-sports sandbox, from the Steep team, with an easy rewind button and fast switching between sports that keep momentum high.",c:"Heavily online: much of the content and the mass races need servers, there is cosmetic monetization, and the PS4 version runs at lower resolution and draw distance than current-gen versions.",r:"Fun for its sense of freedom and quick sport-switching, but the online dependence makes its long-term value uncertain on disc.",b:"Standalone physical PS4 disc from Ubisoft, October 2021; online servers are needed for most modes on that disc.",p:"MAYBE cheap."},
{t:"Gungrave G.O.R.E.",s:"Iggymob's 2022 return to the Gungrave series follows undead gunslinger Grave through stylish, linear third-person shootouts built around chaining kills for beat-meter combo bonuses and Demolition Shots.",w:"It is a rare modern revival of a cult PS2 action series, and its combo-focused gunplay with a coffin-based arsenal is unlike most contemporary shooters.",c:"Budget presentation, repetitive corridor stages, sharp difficulty spikes and a mid-length campaign; it is very much a B-tier action game.",r:"Worth it for fans of over-the-top PS2-era action who enjoy a combo meter; others may find it rough and repetitive.",b:"Physical North American PS4 release; recorded separately from older Gungrave entries in the census.",p:"MAYBE cheap."},
{t:"Persona 5 Tactica",s:"Atlus's 2023 tactics spin-off places the Phantom Thieves in grid-based battles across new Kingdoms ruled by tyrants, with flanking 'One More' attacks and team-up Triple Threat moves.",w:"It offers a genuinely good tactics system with the Persona 5 cast, fast and readable maps, and a story led by new characters Erina and Toshiro.",c:"Map objectives are simple and challenge is low on default settings; the new characters carry more of the story than the familiar Thieves do.",r:"A polished, accessible tactics game that respects your time with quick, punchy battles and strong Persona style.",b:"Physical PS4 Launch Edition from Sega/Atlus, November 2023 (UPC 730865220618); launch packaging does not create a separate identity.",p:"BUY cheap."},
{t:"Babylon's Fall",s:"PlatinumGames and Square Enix's 2022 co-op action RPG, set around climbing the Tower of Babylon, built around Gideon Coffin devices that allow four weapon slots at once.",w:"It is a historical record of one of the shortest-lived major retail releases on PS4: an always-online game whose servers closed in February 2023, making the disc a collector curio.",c:"The game is no longer playable at all because it required online servers; the disc preserves packaging and installation data only.",r:"Include it as a historical oddity rather than a game to play; it matters on a physical shelf precisely because it cannot be played any other way now.",b:"Official physical PS4 release from Square Enix, March 2022; the servers closed on 2023-02-27, so ownership is archival.",p:"COLLECTOR ONLY cheap."},
{t:"Curse of the Sea Rats",s:"Petoons Studio's 2023 hand-drawn Metroidvania, where four human prisoners transformed into rats by a pirate witch explore an interconnected Irish coast, swapping characters with distinct combat styles.",w:"It offers beautiful 2D animation, a sizeable interconnected map and drop-in local co-op for up to four players, which is uncommon in the genre.",c:"Combat and hit detection feel stiff compared with genre leaders, progression can be slow, and there were technical bugs at launch.",r:"A charming-looking Metroidvania best for co-op groups; solo players with high genre standards may prefer stronger options.",b:"Physical PS4 retail release from PQube; GameStop lists it as a PS4 disc.",p:"MAYBE cheap."},
{t:"Willy Morgan and the Curse of Bone Town",s:"Volens Nolens' point-and-click adventure follows teenage Willy Morgan to the pirate-haunted Bone Town to find his father, an archaeologist, with classic inventory puzzles and hand-painted scenes.",w:"It is a loving homage to LucasArts-style adventures, with humor and puzzle design that suit players who miss Monkey Island-era structure.",c:"Some puzzles rely on old-fashioned leaps of logic, and the controller interface is slower than mouse play; the story is light.",r:"A good, cozy adventure for genre fans who enjoy comedy and pirate lore; not much here for players who dislike inventory puzzles.",b:"Physical PS4 retail copy from GS2 Games; GameStop lists it as a PS4 disc.",p:"MAYBE cheap."},
{t:"The Grinch: Christmas Adventures",s:"Outright Games' 2023 holiday platformer has the Grinch and Max sneaking through Whoville and beyond to steal Christmas, with simple collectathon levels and two-player co-op.",w:"It is a gentle, licensed family platformer suited to a holiday shelf, with easy controls and co-op that make it approachable for young players.",c:"Short and simple, with basic level design and limited challenge; adults playing alone will get little out of it.",r:"A family pick for December rather than a standout platformer; it does exactly what a licensed kids' game should do and not much more.",b:"Physical PS4 release from Outright Games, October 2023; the 2024 Holiday Edition reissue is an edition of the same game.",p:"MAYBE cheap."},
{t:"Gabby's Dollhouse: Ready to Party",s:"Outright Games' licensed preschool game based on the DreamWorks series has players exploring Gabby's Dollhouse rooms, decorating and playing simple mini-games with Gabby and Pandy Paws.",w:"It is a genuinely child-first game with gentle mechanics and no fail states, matched to the show's youngest audience.",c:"Designed for very young children only; there is little challenge or depth, and older players will find almost nothing to do.",r:"Include for completeness and for a household with young fans; it has no appeal beyond its target age group.",b:"Physical PS4 disc sold at Target, Best Buy and Argos under the DreamWorks Gabby's Dollhouse: Ready to Party title.",p:"WAIT cheap."},
{t:"Sniper Elite: Resistance",s:"Rebellion's 2025 Sniper Elite entry follows SOE agent Harry Hawker through occupied France, with large sandbox maps, the series' X-ray kill cam and two-player co-op.",w:"It is the newest Sniper Elite on PS4 and keeps the series' best formula: open-ended stealth sniping, strong map design and co-op across the full campaign.",c:"It plays very similarly to Sniper Elite 5, with modest innovation, and PS4 performance and visuals trail the current-gen versions.",r:"A dependable, satisfying stealth-shooter for series fans; quick to pick up and rewarding for players who enjoy planning a perfect shot.",b:"Physical PS4 disc from Rebellion, January 2025; library records describe it as a single PS4 Blu-ray.",p:"BUY cheap."},
{t:"The Rumble Fish 2",s:"Dimps' 2005 arcade fighter returns in a 2022 remaster with high-resolution sprites, rollback netcode, and a roster of street fighters using a two-gauge Offense and Defense system.",w:"It is a cult arcade fighter that rarely saw a home release, now playable with modern online code and its distinctive damage-visible character art.",c:"The roster is small by modern standards, the single-player content is thin, and its systems are deep enough that casual players may bounce off.",r:"A strong niche pick for fighting game collectors who value rare arcade history and tight, technical fundamentals.",b:"Region-free physical PS4 disc via Limited Run Games, with Japanese standard and collector's physical releases in December 2022.",p:"MAYBE cheap."},
{t:"God of War Ragnarök",s:"Santa Monica Studio's 2022 sequel follows Kratos and Atreus as Fimbulwinter heralds Ragnarök, traveling all nine Norse realms in a story about fate and fatherhood.",w:"One of the PS4's final first-party showpieces, with superb combat, high production values and outstanding performances, and a full version that runs on base PS4 hardware.",c:"It is long and heavily narrative, with frequent companion banter and puzzle hints; pacing slows during the sections where you play as Atreus.",r:"Essential for the PS4 shelf: a definitive late-generation first-party game with exceptional combat and a satisfying conclusion to the Norse saga.",b:"Sony PS4 Standard Edition on two Blu-ray discs (CUSA34384); later Valhalla content was a free download.",p:"TOP-TIER buy."},
{t:"Dying Light 2 Stay Human",s:"Techland's 2022 open-world zombie sequel moves the parkour survival formula to the city of Villedor, where factions vie for control and dangerous Infected rule the night.",w:"Its parkour is excellent and the day-night tension remains distinctive, with a paraglider and grappling hook adding traversal variety over the original.",c:"The PS4 version runs at lower resolution with long load times; the story and faction choices are weaker than the movement, and post-launch patches changed balance considerably.",r:"A strong action sandbox for players who love movement and nighttime survival pressure, even if the narrative underwhelms.",b:"Physical PS4 retail disc (Target lists it as physical format); the PS4 copy includes a free PS5 upgrade.",p:"BUY cheap."},
{t:"Ys IX: Monstrum Nox",s:"Falcom's 2021 Western release sends Adol to the prison city of Balduq, where he gains the powers of a Monstrum and joins other cursed heroes defending the city each night.",w:"It keeps the series' fast, satisfying action combat and adds traversal powers like wall running and gliding, making exploring Balduq unusually vertical for an Ys game.",c:"The city setting is gray and repetitive compared with Ys VIII's island, the PS4 version has a modest frame rate, and the story pacing drags in the middle.",r:"A good action RPG with brisk combat and charming cast, ideal for Ys fans; newcomers may want to start with Ys VIII.",b:"Physical PS4 release from NIS America, February 2021, including the Pact Edition with soundtrack and artbook.",p:"BUY cheap."},
{t:"SpongeBob SquarePants: The Cosmic Shake",s:"Purple Lamp's 2023 3D platformer sends SpongeBob and balloon-Patrick across wish-made worlds themed on genres from Westerns to prehistory, after a mermaid's bubbles break Bikini Bottom.",w:"It captures the show's humor well, has charming costumes and voice cast, and is a solid follow-up to the well-liked Battle for Bikini Bottom remake.",c:"The platforming is simple and occasionally imprecise, camera issues appear in tighter sections, and the game is short.",r:"A good-natured licensed platformer that respects the source material; best for fans and families.",b:"Physical PS4 disc from THQ Nordic, January 2023; collector's and BFF editions are packaging of the same game.",p:"MAYBE cheap."},
{t:"Five Nights at Freddy's: Security Breach",s:"Steel Wool's 2021 free-roam entry has Gregory hiding inside the Mega Pizzaplex overnight, evading reimagined animatronics with help from a damaged Glamrock Freddy.",w:"It turns the series' static horror into a large stealth exploration game, with a colorful 80s mall aesthetic and memorable animatronic designs.",c:"Save points are sparse, the open structure is confusing, and the launch version had notable bugs; it is less scary than tense and frustrating at times.",r:"Worth owning for series fans curious to see the franchise go 3D; others should expect a messy but ambitious stealth game.",b:"Maximum Games physical PS4/PS5 edition, March 2022 (NA April); PSVR is not involved.",p:"MAYBE cheap."},
{t:"Outriders",s:"People Can Fly's 2021 co-op looter shooter casts you as an Altered on the hostile planet Enoch, combining cover shooting with aggressive class powers that heal through damage.",w:"Its four classes reward aggression rather than hiding, and the full campaign supports three-player co-op with satisfying, fast-paced combat.",c:"Always online, even solo, with launch-era server problems; the story is clichéd and the loot grind repeats content heavily.",r:"A fun co-op shooter for a few weekends, with distinctive power-driven combat; long-term value depends on server availability.",b:"Physical PS4 Day One Edition from Square Enix, April 2021; the disc still requires an online connection to play.",p:"MAYBE cheap."},
{t:"Kingdom Hearts: Melody of Memory",s:"Square Enix's 2020 rhythm game retells the Kingdom Hearts saga through over 140 songs from the series, with Sora, Riku and friends attacking enemies to the beat.",w:"It is the most complete collection of Yoko Shimomura's series music in game form, with a world tour mode that recaps the saga.",c:"The narrative is a recap with only a small new story at the end; difficulty spikes and fixed song choices may frustrate rhythm newcomers.",r:"A celebration piece for series fans with good music; casual players can skip it without missing anything important.",b:"Physical PS4 release from Square Enix, November 2020, sold as a standard retail disc in North America and Europe.",p:"MAYBE cheap."},
{t:"Far Cry 6",s:"Ubisoft's 2021 open-world shooter puts guerrilla Dani Rojas against dictator Antón Castillo, played by Giancarlo Esposito, on the fictional Caribbean island of Yara.",w:"It offers a huge, dense open world with lots of activities, makeshift Resolver weapons and amigo companions, with full co-op across the campaign.",c:"Formulaic map clearing, a gear system that adds friction, and a tone that swings between satire and seriousness; the PS4 version trails newer platforms visually.",r:"A competent, lavish Far Cry that delivers more of the same; enjoyable in co-op, but the formula is familiar.",b:"Physical PS4 Blu-ray release from Ubisoft, October 2021, on a single disc that also offers a PS5 upgrade.",p:"MAYBE cheap."},
{t:"Street Fighter 6",s:"Capcom's 2023 fighting game reboots the series with the Drive system, modern control options, a World Tour open-world RPG mode and the Battle Hub online lobby.",w:"It is one of the best fighting games ever made, with deep systems, accessible Modern controls and a generous single-player offering for a fighting game.",c:"Some content and new characters are paid DLC; World Tour mode is uneven, and PS4 visuals and load times are lower than current-gen.",r:"Essential for any fighting game shelf; few modern fighters respect newcomers and experts as well.",b:"Physical PS4 disc from Capcom, June 2023, including standard and collector's editions.",p:"STRONG buy."},
{t:"Sonic Colors: Ultimate",s:"Sega's 2021 remaster of the 2010 Wii game sends Sonic to Dr. Eggman's interstellar amusement park, using Wisp aliens for color-coded transformations.",w:"Sonic Colors is one of the best-liked 3D Sonic games, and the remaster adds a smoother frame rate and higher resolution.",c:"The remaster shipped with glitches and lighting issues, and the level design is short with a lot of 2D sections.",r:"A brisk, cheerful Sonic platformer that works well in short sessions; good for fans and families.",b:"Physical PS4 release from Sega, September 2021, including the Launch Edition with a Baby Sonic keychain.",p:"BUY cheap."},
{t:"The Crew Motorfest",s:"Ubisoft Ivory Tower's 2023 open-world racer takes place on a compact version of the Hawaiian island of Oahu, with themed Playlists celebrating car cultures, plus planes and boats.",w:"It is a major improvement over The Crew 2, with a gorgeous setting and curated Playlists that turn open-world racing into themed tours.",c:"Always online with microtransactions; the PS4 version has lower visual quality, and the long-term playability depends on Ubisoft's servers.",r:"A pretty, polished arcade racer for its present lifespan; ownership value depends on the servers.",b:"Physical PS4 disc from Ubisoft, September 2023, with a PS5 upgrade for PS4 disc owners.",p:"MAYBE cheap."},
{t:"Gran Turismo Sport",s:"Polyphony Digital's 2017 racing sim focuses on FIA-sanctioned online competition, with a sportsmanship rating system, Brand Central museum and a curated set of cars and tracks.",w:"It is a gorgeous sim with superb handling, and the GT League and Driving School content remains a strong solo experience.",c:"Online servers shut down in January 2024, removing online races and sharply limiting what is accessible without online connection.",r:"Still worth owning as the PS4's flagship racer, though much of its design centered on online play that no longer exists.",b:"Physical PS4 Blu-ray from Sony, October 2017, including later PlayStation Hits reprints of the same game.",p:"MAYBE cheap."},
{t:"Gran Turismo 7",s:"Polyphony Digital's 2022 racing sim returns to a full campaign built around Café menus, a car collection and licenses, with over 400 cars and many classic tracks.",w:"It is the most complete Gran Turismo in years, with excellent handling, the brand's celebration of car culture, and a full PS4 version.",c:"Needs online connection for most of the game, including the campaign; microtransactions and slow early progression drew criticism.",r:"A great sim racer for car lovers, but its always-online design makes long-term ownership uncertain.",b:"Physical PS4 disc from Sony, March 2022; PlayStation Direct sells the PS4 disc version.",p:"BUY cheap."},
{t:"Jurassic World Evolution 2",s:"Frontier's 2021 park management sequel adds Chaos Theory scenarios from the Jurassic films, new marine and flying reptiles, and expanded dinosaur behaviour and territories.",w:"It is a deeper and more polished park builder than the original, with impressive dinosaur animation and plenty of sandbox options.",c:"Management systems can feel repetitive, and the console interface is fiddly; key content is in paid DLC.",r:"A good management game for dinosaur fans who want to build and watch their park run.",b:"Physical PS4 disc from Frontier, November 2021, with a free PS5 upgrade.",p:"MAYBE cheap."},
{t:"Dynasty Warriors 9: Empires",s:"Omega Force's 2021 strategy spinoff combines Dynasty Warriors 9 musou combat with territory control, siege battles and a politics layer for building your own warlord.",w:"It drops Dynasty Warriors 9's open world in favor of focused sieges and kingdom building, the elements Empires fans enjoy.",c:"Reused assets from Dynasty Warriors 9, a shallow strategy layer and repetitive battles; it is a niche spin-off.",r:"For musou fans who want army management with their crowd battles; everyone else may find it repetitive.",b:"Physical North American PS4 Blu-ray from Koei Tecmo, February 2022 (UPC 040198003247), sold as a standard edition.",p:"WAIT cheap."},
{t:"Call of Duty: Black Ops Cold War",s:"Treyarch and Raven's 2020 Call of Duty is set in the early 1980s, with a branching spy campaign led by Russell Adler, round-based Zombies and online multiplayer.",w:"Its campaign is among the most inventive in the series, with evidence-based optional missions and multiple endings, plus a strong Zombies mode.",c:"Multiplayer and Zombies depend on servers, and large updates are required; the campaign is relatively short.",r:"Worth keeping for the campaign and couch-playable Zombies; the online portion has a limited lifespan.",b:"Physical PS4 Standard Edition from Activision, November 2020; cross-gen bundles are packaging of the same game.",p:"MAYBE cheap."},
{t:"Call of Duty: Black Ops 6",s:"Treyarch and Raven's 2024 Call of Duty is set during the 1991 Gulf War, with a spy-thriller campaign, omnimovement that allows diving in any direction, and round-based Zombies.",w:"Omnimovement freshened the series' gunplay, and the campaign has varied missions, including a heist and a horror-themed level.",c:"Requires continuous internet connection and large downloads; many features depend on Activision's servers.",r:"A good campaign and enjoyable movement, but heavily online; buy it for the PS4 shelf, not for longevity.",b:"PS4 Cross-Gen Bundle from Activision includes a version playable on PS4 plus a PS5 digital code; the disc is the qualifying product.",p:"MAYBE cheap."},
{t:"Call of Duty: Black Ops 7",s:"Treyarch and Raven's 2025 Black Ops sequel, set in 2035, continues the story of Black Ops II with a co-op-oriented campaign, omnimovement, multiplayer and Zombies.",w:"It is the newest mainline Call of Duty released on PS4 and continues the Black Ops II storyline with returning characters like David Mason.",c:"Requires continuous internet connection and large installs; much of the content depends on servers that will eventually close.",r:"Include for completeness of the PS4 era; long-term playability is uncertain due to its online requirements.",b:"PS4 Cross-Gen Bundle from Activision includes a version playable on PS4 plus a PS5 digital code; the disc is the qualifying product.",p:"WAIT cheap."},
{t:"Call of Duty: Modern Warfare II",s:"Infinity Ward's 2022 sequel follows Task Force 141 from Captain Price to Ghost through a campaign spanning Amsterdam, Mexico and Chicago, with Spec Ops co-op and multiplayer.",w:"Its campaign has several memorable missions, like the stealth Alone and the oil rig assault, and the gunplay is strong.",c:"Requires online connection and large updates; DMZ and online modes depend on servers, and the campaign ends abruptly.",r:"A solid campaign for series fans, though online features will degrade over time.",b:"PS4 Cross-Gen Edition from Activision includes a version playable on PS4 plus a PS5 digital upgrade.",p:"MAYBE cheap."},
{t:"Call of Duty: Modern Warfare III",s:"Sledgehammer Games' 2023 Call of Duty pits Task Force 141 against Makarov, with open-ended Open Combat Missions, remastered Modern Warfare 2 multiplayer maps and an open-world Zombies.",w:"It completes the rebooted Modern Warfare trilogy and has a well-liked multiplayer offering built around classic maps.",c:"The campaign is short and widely considered the series' weakest; online requirements and large installs apply.",r:"Primarily a multiplayer package built on classic maps; collectors should know that its campaign is thin and short.",b:"PS4 Cross-Gen Edition from Activision includes a version playable on PS4 plus a PS5 digital upgrade.",p:"WAIT cheap."},
{t:"LEGO 2K Drive",s:"Visual Concepts' 2023 open-world kart racer lets you drive across LEGO-built Bricklandia, transforming between land, water and off-road vehicles and building custom cars from bricks.",w:"It has a deep vehicle builder and charming open world, with smooth transformations between vehicle types that keep races lively.",c:"Heavy microtransactions and a grindy currency system, plus online requirements for some features.",r:"A creative family racer for LEGO fans with a great vehicle builder, though the monetization undercuts it noticeably.",b:"Physical PS4 Standard and Awesome Edition discs from 2K, May 2023; the Awesome Edition adds bonus content only.",p:"MAYBE cheap."},
{t:"Rust: Console Edition",s:"Facepunch and Double Eleven's 2021 console port of the multiplayer survival game, where players scavenge, build bases and raid or ally with others on persistent servers.",w:"It is one of the defining online survival games, and the console edition brings its emergent player stories to PS4.",c:"Online-only, with a punishing community and wipe cycles; the console version lags the PC game's updates.",r:"Only for players who want hardcore online survival; worthless offline, and dependent on official servers.",b:"Physical PS4 Day One Edition from Koch Media/Deep Silver, May 2021; the disc is useless without official servers.",p:"WAIT cheap."},
{t:"Nickelodeon All-Star Brawl 2",s:"Ludosity and Fair Play Labs' 2023 platform fighter brings Nickelodeon characters like SpongeBob, Danny Phantom and Aang into Smash-style arenas, now with voice acting and a roguelite campaign.",w:"It improves on the original with voice acting, a single-player campaign and a deeper roster, while keeping the tight platform fighting.",c:"Some roster choices and the campaign's repetition are weaker; online community is small.",r:"A fun party fighter for Nickelodeon fans that works best with friends playing together locally on one console.",b:"Physical PS4 Blu-ray from GameMill (UPC 810110660700), November 2023, sold as a standard edition at major retailers.",p:"MAYBE cheap."},
{t:"Battlefield 2042",s:"DICE's 2021 near-future Battlefield drops the campaign for large online battles across Conquest, Breakthrough and the Portal custom-game mode; PS4 caps matches at 64 players.",w:"Portal lets players recreate classic Battlefield modes and maps, which is the strongest part of the package.",c:"Online-only with no campaign; the launch was buggy and the PS4 version has fewer players than current-gen platforms.",r:"Primarily for active Battlefield fans; without servers, there is little reason to keep the disc.",b:"Physical PS4 disc from EA, November 2021; with no campaign, the disc is only playable while servers remain online.",p:"WAIT cheap."},
{t:"Hitman 3",s:"IO Interactive's 2021 finale to the World of Assassination trilogy sends Agent 47 to Dubai, Dartmoor, Berlin, Chongqing, Mendoza and the Carpathian Mountains.",w:"Its levels, especially the Dartmoor murder mystery and Berlin's open hunt, are among the series' best, with endless replay through creative kills.",c:"Requires online connection for unlocks and progression; content carries over from earlier games inconsistently between platforms.",r:"An essential stealth sandbox that respects your creativity; a top-tier PS4 shelf pick.",b:"Physical PS4 editions distributed by Square Enix in 60 countries, January 2021.",p:"STRONG buy."},
{t:"The Texas Chain Saw Massacre",s:"Sumo Digital and Gun Interactive's 2023 asymmetric multiplayer horror game puts four victims against three members of the Slaughter family in matches based on the 1974 film.",w:"It recreates the film's dirty, claustrophobic atmosphere well, with three-killer gameplay that differs from Dead by Daylight.",c:"Online-only with no meaningful single-player; new content development ended in 2024, so its future playability depends on servers staying up.",r:"A collector's piece for horror fans, but ownership depends on servers and community.",b:"Physical PS4 Blu-ray from Gun Media, 2023; the disc needs online servers because there is no offline mode.",p:"WAIT cheap."},
{t:"Farming Simulator 22",s:"Giants Software's 2021 farming sim adds production chains, seasonal cycles and new crops like grapes and olives across three maps, with hundreds of licensed machines.",w:"It is the most complete farming sim on PS4, with deeper production systems and seasons that add planning.",c:"Slow-paced and fiddly with a controller; requires patience and some knowledge of farming systems.",r:"A great relaxing sim for players who enjoy long-term management; not for those seeking action.",b:"Boxed disc on PS4 from Giants Software; the copy is playable on PS4 (PS4/PS5 versions).",p:"MAYBE cheap."},
{t:"MX vs. ATV Legends",s:"Rainbow Studios' 2022 off-road racer adds trophy trucks and UTVs to motocross and ATV racing, with a career mode and open-world trail riding.",w:"It offers a broad range of off-road vehicles and an open trail world, appealing to players who enjoy the series' physics.",c:"The launch version had bugs and performance issues, and the physics take time to master; presentation is dated.",r:"For off-road racing fans who want variety; others may find it rough.",b:"Physical PS4 release from THQ Nordic/Plaion, May 2022, sold as a boxed disc in Europe and North America.",p:"WAIT cheap."},
{t:"Cabela's African Adventures",s:"Activision and Cauldron's 2015 hunting game takes players on safari across African regions, tracking lions, elephants and other big game in linear stalking missions with scripted predator attacks.",w:"It is one of the few Cabela's games released on PS4, representing the long-running budget hunting series' last console generation.",c:"Linear, repetitive levels, dated visuals and simple shooting; animal-attack sequences rely on quick reflex shooting rather than real hunting.",r:"A franchise-completion piece for hunting game fans; there is little here for anyone else beyond a few novelty sessions.",b:"Physical PS4 disc from Activision, 2015 (UPC 0047875770591); disc-only copies are common in the used market.",p:"WAIT cheap."},
{t:"ATV Drift & Tricks",s:"Microids and Artefacts Studio's 2017 arcade quad-bike racer mixes race tracks, open trick arenas and stunt scoring across sunny off-road locations, with split-screen multiplayer.",w:"It is an easygoing, arcade-style off-road racer with a trick system that suits casual players and local multiplayer sessions.",c:"Physics are floaty, track variety is limited and the presentation is budget; it lacks the depth of dedicated motocross games.",r:"A light, pick-up-and-play racer for families or split-screen; few reasons to choose it over stronger racers.",b:"Physical PS4 disc via Maximum Games, sold as the Definitive Edition; it is playable without a VR headset.",p:"WAIT cheap."},
{t:"Big Rumble Boxing: Creed Champions",s:"Survios' 2021 arcade boxing game features Rocky Balboa, Adonis Creed, Ivan Drago and other film boxers in fast, combo-based bouts with an arcade story mode.",w:"It is a fun, accessible arcade brawler with recognizable characters from the Rocky and Creed films, and it suits casual couch versus play.",c:"The roster is small, the combat is simple and the single-player content can be finished quickly.",r:"A good party-friendly boxing game for film fans; brief, but enjoyable in short bursts.",b:"Physical PS4 Day One Edition published at retail by Koch Media, September 2021, with a bonus poster.",p:"MAYBE cheap."},
{t:"Dynasty Warriors 8: Xtreme Legends",s:"Omega Force's 2014 expansion of Dynasty Warriors 8 adds new characters, Legend Mode and Challenge Mode; the PS4 Complete Edition includes the full base game and all additions.",w:"Dynasty Warriors 8 is widely considered the high point of the series, and Xtreme Legends Complete Edition is the most complete version.",c:"Repetitive musou combat over many battles; the visuals are a PS3-era port, and newcomers may find the content overwhelming.",r:"The best version of the series' best entry; recommended for musou fans who enjoy long play sessions.",b:"Physical PS4 retail release as Dynasty Warriors 8: Xtreme Legends Complete Edition from Koei Tecmo, 2014.",p:"BUY cheap."},
{t:"Need for Speed: Hot Pursuit Remastered",s:"Stellar Entertainment and Criterion's 2020 remaster of the 2010 racer pits Racers against Police across the open roads of Seacrest County, with cross-play and Autolog leaderboards.",w:"Hot Pursuit is one of the best-loved Need for Speed games, and the remaster adds a higher resolution, extra content and DLC.",c:"Visual upgrades are modest, and the core design is a decade old; there is no split-screen, and some online features depend on EA servers.",r:"A great, fast, approachable racer that respects your time with short, intense events.",b:"Physical PS4 disc from EA, November 2020, sold as a single Blu-ray with all original DLC included.",p:"BUY cheap."},
{t:"World of Outlaws: Dirt Racing",s:"iRacing and Monster Games' 2023 racing game covers sprint car and late model dirt oval racing on licensed World of Outlaws tracks, with a career mode.",w:"It is a rare authentic dirt-oval racing sim on console, with demanding handling and real teams and drivers.",c:"Its narrow focus on oval dirt racing and steep learning curve make it niche; presentation is modest.",r:"A good pick for dirt racing fans who enjoy sim handling; everyone else can skip it.",b:"Physical PS4 edition, sold at Walmart and other retailers; the physical edition is PS4-only with a PS5 download entitlement.",p:"WAIT cheap."},
{t:"Five Nights at Freddy's: Help Wanted",s:"Steel Wool's 2019 collection of minigames reimagines the Five Nights at Freddy's series as an in-universe virtual reality experience, with classic night-shift recreations, vent repairs and new horror scenarios.",w:"It is the best way to play the classic Five Nights at Freddy's scenarios on PS4, and the flat mode lets non-VR players enjoy it.",c:"Originally designed for VR, so flat mode is less immersive; minigames vary in quality, and jump scares get repetitive.",r:"Recommended for series fans; the flat-screen mode makes it a complete horror sampler without needing a headset.",b:"Maximum Games physical release, December 2020; the disc supports non-VR flat mode, so PSVR is optional rather than required.",p:"MAYBE cheap."},
{t:"Persona 3 Reload",s:"Atlus's 2024 full remake of Persona 3 rebuilds SEES's battles in the Dark Hour, Tartarus and the school-life calendar in the Persona 5 engine, with new Theurgy attacks and voiced social links.",w:"It is a definitive modern version of a classic JRPG, with excellent music, a polished interface and a story about mortality.",c:"The Answer epilogue and female protagonist route were not included in the base game; Tartarus floors can feel repetitive.",r:"A top-tier JRPG that respects players with quality-of-life improvements; essential for Persona fans.",b:"Physical PS4 Standard Edition from Atlus/Sega, February 2024, released alongside PS5 and Xbox versions.",p:"STRONG buy."},
{t:"Dishonored: Death of the Outsider",s:"Arkane's 2017 standalone expansion follows assassin Billie Lurk and Daud on a mission to kill the Outsider, the god-like figure behind the series' supernatural powers.",w:"It distills Dishonored 2's excellent level design into a shorter campaign, with new abilities like Displace and contract side missions.",c:"Shorter than the main games and lacks the chaos system; it assumes familiarity with the series' story.",r:"A compact, superbly crafted stealth adventure that respects your time; a great pick for immersive sim fans.",b:"Physical PS4 disc from Bethesda, September 2017 (UPC 093155172265), sold as a standalone release.",p:"BUY cheap."},
{t:"Stranger of Paradise Final Fantasy Origin",s:"Team Ninja and Square Enix's 2022 action RPG reimagines the original Final Fantasy, as Jack Garland and companions set out to kill Chaos in a dark, Souls-like reinterpretation.",w:"Its job system and combat, especially the Soul Shield parry, make it a deep, flexible action game with lots of build variety.",c:"The PS4 version has lower resolution and frame rates; its story is deliberately strange, and loot management is cumbersome.",r:"A fun, combat-focused action RPG with a cult following; best for players who enjoy Team Ninja's style.",b:"Physical PS4 Standard Edition from Square Enix, March 2022; Target lists it as a physical-format PS4 release.",p:"MAYBE cheap."},
{t:"Wo Long: Fallen Dynasty",s:"Team Ninja's 2023 Souls-like action RPG is set in a dark fantasy Three Kingdoms China, focusing on deflection-based combat, morale ranks and Five Phase wizardry.",w:"It delivers fast, aggressive combat built around deflecting, and the flag system gives exploration a clear sense of progression.",c:"Level design is weaker than Team Ninja's Nioh games, PS4 performance is limited, and difficulty spikes may frustrate newcomers.",r:"A strong action game for Souls-like fans who prefer aggression to caution.",b:"Physical PS4 Standard and SteelBook Launch Edition from Koei Tecmo, March 2023; the launch SKU is packaging only.",p:"MAYBE cheap."},
{t:"Deer Hunter Reloaded",s:"GameMill's 2017 hunting game is a budget port of the mobile Deer Hunter series, with short hunts for deer and other game in a few outdoor environments.",w:"It represents the Deer Hunter brand's PS4 appearance and offers simple, arcade-style hunting for casual players.",c:"Thin content, dated visuals and mobile-style design; there is very little to do beyond repeating similar hunts.",r:"Include only for completeness; it is a budget title with little lasting appeal.",b:"Physical PS4 disc from GameMill, October 2017 (UPC 0834656000431); disc-only and complete copies circulate used.",p:"WAIT cheap."},
{t:"Police Simulator: Patrol Officers",s:"Aesir Interactive's 2022 police simulator has you patrolling the city of Brighton as a new officer, writing tickets, managing traffic and responding to calls in solo or co-op play.",w:"It is a calm, procedure-focused sim with two-player co-op and a slow progression through districts and duties.",c:"Repetitive tasks, stiff AI and limited variety; it is a sim for patient players who enjoy routine.",r:"A niche sim for players who enjoy everyday routines; others will find it dull quickly.",b:"Physical PS4 disc from astragon, November 2022, including a limited Steelbook Edition at retail.",p:"WAIT cheap."},
{t:"RollerCoaster Tycoon Adventures Deluxe",s:"Atari's 2023 console edition of RollerCoaster Tycoon Adventures lets players build theme parks with custom coasters, shops and scenarios, adding new rides and themes to the original package.",w:"It is the only full RollerCoaster Tycoon park builder on PS4, with an accessible controller interface.",c:"Management systems are simpler than classic RollerCoaster Tycoon or Planet Coaster; the visuals are basic.",r:"A casual park builder for families or newcomers; Planet Coaster is deeper for serious fans.",b:"Physical PS4 disc from Atari, November 2023, released two days after the digital launch; distinct from RollerCoaster Tycoon Joyride.",p:"WAIT cheap."},
{t:"Assetto Corsa Competizione",s:"Kunos Simulazioni's 2019 racing sim is the official game of the GT World Challenge, with GT3 and GT4 cars, laser-scanned circuits and a dynamic weather system.",w:"It offers some of the best GT handling physics available on console, with an authentic championship structure.",c:"The PS4 version runs at lower resolution and frame rate, its content is narrow, and the game demands a steering wheel for best results.",r:"An excellent sim for dedicated GT racing fans; not a casual racer.",b:"Physical PS4 disc from 505 Games, June 2020 (UPC 812872019901); the later Day One Edition was PS5/Xbox only.",p:"MAYBE cheap."},
{t:"DreamWorks All-Star Kart Racing",s:"GameMill's 2023 kart racer features DreamWorks characters from Shrek, Kung Fu Panda, Madagascar and How to Train Your Dragon on themed tracks with items and drifting.",w:"It is a gentle kart racer for younger players who love DreamWorks films, with recognizable characters.",c:"Simple tracks, modest presentation and limited depth; it is far behind leaders in the kart racing genre.",r:"A family pick for young DreamWorks fans; experienced racers will tire of it quickly.",b:"Physical PS4 disc from GameMill, November 2023 (UPC 810110660786), sold at major retailers.",p:"WAIT cheap."},
{t:"Granblue Fantasy: Relink",s:"Cygames' 2024 action RPG follows the Captain and the crew of the Grandcypher through the Zegagolla sky realm, with fast, four-character combat and a large post-game.",w:"It has excellent character variety and flashy combat, with satisfying endgame content and strong production values.",c:"The story campaign is short compared to the endgame grind, and the PS4 version runs at reduced performance.",r:"A great co-op action RPG for players who enjoy refining builds and chasing endgame content.",b:"Physical PS4 Standard Edition from Cygames, February 2024; Deluxe and Collector's editions are packaging of the same game.",p:"BUY cheap."},
{t:"Fatal Fury: City of the Wolves",s:"SNK's 2025 revival of the Fatal Fury series continues Garou: Mark of the Wolves with Terry Bogard, Rock Howard and new fighters, adding the REV system and the S.P.G. (Selective Potential Gear) comeback mechanic.",w:"It is the first new Fatal Fury in over 25 years, with a strong art style and accessible Smart Style controls.",c:"Guest characters drew criticism, the single-player content is modest, and the PS4 version trails PS5 visually.",r:"A must for fighting game fans who love SNK history, and a welcoming entry point thanks to Smart Style controls.",b:"Physical PS4 Special Edition from SNK, April 2025, with the base game on disc plus a Season Pass 1 code.",p:"BUY cheap."},
{t:"Werewolf: The Apocalypse Earthblood",s:"Cyanide's 2021 action RPG casts you as Cahal, a Garou who can shift between human, wolf and Crinos werewolf forms to fight the oil corporation Endron.",w:"Its Crinos combat delivers a satisfying power fantasy, and the World of Darkness setting is rarely adapted in console games.",c:"Stealth sections are basic, the level design is repetitive, and the budget presentation is clear throughout.",r:"A flawed but enjoyable B-game for World of Darkness fans who want to play as a raging werewolf.",b:"Physical PS4 Blu-ray from Nacon, with US distribution by Maximum Games (UPC 814290015909), February 2021.",p:"WAIT cheap."},
{t:"Looney Tunes: Wacky World of Sports",s:"GameMill and Bamtang's 2024 party sports game puts Bugs Bunny, Daffy Duck and other Looney Tunes characters into slapstick versions of several ball sports for local multiplayer.",w:"It is a cheerful, family-friendly multiplayer game with recognizable characters and simple controls for younger players.",c:"Short on depth and variety; each sport is shallow, and it is best only with local multiplayer.",r:"A light family party game for fans of the cartoons; not much replay value beyond that.",b:"Physical PS4 disc from GameMill, September 2024; Target and The Game Collection list it as a physical disc.",p:"WAIT cheap."},
{t:"MX vs. ATV Supercross Encore",s:"Rainbow Studios' 2017 PS4 edition of MX vs. ATV Supercross adds vehicles, tracks and bike customization to the series' motocross and ATV racing.",w:"It is the series' first PS4 entry, and its motocross physics and track editor keep it appealing for off-road fans.",c:"Dated visuals, sparse content and a steep learning curve; later MX vs. ATV games offer more.",r:"For dedicated off-road fans only; casual players should pick a more modern racer.",b:"Physical PS4 disc from THQ Nordic, 2017; boxed copies are mostly found used today.",p:"WAIT cheap."},
{t:"Exoprimal",s:"Capcom's 2023 online team shooter pits squads of exosuit-wearing fighters against dinosaur hordes and each other in Dino Survival matches, framed by a time-loop story about an AI called Leviathan.",w:"Its dinosaur horde battles are a unique spectacle, and the exosuit roster provides distinctive class roles.",c:"Online-only, with a story unlocked through matches; Capcom ended updates in 2024, so the game's future depends on servers.",r:"A fun novelty while servers last; it is not a long-term single-player investment.",b:"Physical PS4 disc from Capcom, July 2023; Target lists it as a physical-format PS4 release.",p:"WAIT cheap."},
{t:"Farming Simulator 17",s:"Giants Software's 2016 farming sim adds a North American map, new crops like sunflowers and soybeans, and hundreds of licensed machines from brands such as Fendt and Case IH.",w:"It is a solid generation of the series, with deep farming management and console mod support.",c:"Slow-paced and repetitive, with clunky controller handling; later Farming Simulator games improve on it.",r:"For dedicated farm-sim fans who want the series' history; Farming Simulator 22 is the stronger choice today.",b:"Physical PS4 disc from Focus Home/Maximum Games, October 2016; the Platinum Edition disc has not been confirmed.",p:"WAIT cheap."},
{t:"Mount & Blade II: Bannerlord",s:"TaleWorlds' 2022 medieval sandbox RPG lets you rise from wandering warrior to king in the continent of Calradia, managing armies, trade and politics alongside large field battles.",w:"Its large-scale battles and freedom are unique on console, offering a deep sandbox with lots of replay value.",c:"The PS4 version has reduced battle sizes and long load times; the interface is complex and the story mode is thin.",r:"A unique strategy sandbox for patient players who enjoy creating their own medieval story.",b:"Physical PS4 disc from Plaion, October 2022; Target lists it as a physical-format PS4 release.",p:"MAYBE cheap."},
{t:"Miraculous: Paris Under Siege",s:"GameMill's 2024 action game based on Miraculous: Tales of Ladybug and Cat Noir has players switching between the heroes to fight akumatized villains across Paris.",w:"It is a family-friendly licensed adventure that suits young fans of the animated series.",c:"Simple combat, repetitive missions and modest presentation; little challenge for older players.",r:"A licensed kids' game best suited to young fans of the show; older players can safely skip it.",b:"Physical PS4 disc from GameMill, October 2024; retailers list it as a PS4 disc.",p:"WAIT cheap."},
{t:"Road 96",s:"DigixArt's 2021 procedural road-trip adventure follows teenagers fleeing the authoritarian nation of Petria by hitchhiking towards the border before an election, with characters reappearing across runs.",w:"Its blend of narrative choice, varied mini-games and great soundtrack makes each trip feel personal and surprising.",c:"Some segments are uneven and the political messaging is heavy-handed; the randomization can break story pacing.",r:"A charming, inventive narrative game that rewards curiosity; worth owning for narrative fans.",b:"Physical PS4 edition distributed at retail by Merge Games; Target lists it as a physical-format PS4 release.",p:"BUY cheap."},
{t:"Dolphin Spirit: Ocean Mission",s:"Microids' 2023 family adventure has players controlling a young dolphin exploring the ocean, helping marine animals and racing through rings in a gentle, open underwater world.",w:"It is a calm, accessible game for young children, with simple controls and an animal-care theme.",c:"Little challenge or depth; adults will find it repetitive and very short.",r:"A light family pick for young animal lovers; not much beyond that.",b:"Physical PS4 retail edition from Microids, September 2023, sold under the title Dolphin Spirit - Ocean Mission.",p:"WAIT cheap."},
{t:"Trinity Trigger",s:"FuRyu's 2023 action RPG follows Cyan and companions, chosen by the gods of Order and Chaos, as they explore a world scarred by the war of the gods with transforming Trigger weapons.",w:"It is a clear love letter to classic Mana-style action RPGs, with a pleasant three-character party system and weapon-switching Triggers.",c:"Combat is shallow, the story is generic, and there are some technical issues on PS4.",r:"A pleasant, retro-flavored action RPG for fans of Secret of Mana; average otherwise.",b:"Physical PS4 Day 1 Edition from XSEED/FuRyu, April 2023, with artbook and soundtrack; edition is packaging of the same game.",p:"MAYBE cheap."},
{t:"Street Outlaws 2: Winner Takes All",s:"GameMill's 2021 drag racing game based on the Discovery TV show features street racing, car building and tuning, with a story mode and an open environment.",w:"It covers a niche: license-based drag racing with a dedicated tuning system and cars from the show.",c:"Basic driving, rough visuals and limited content; it is aimed squarely at fans of the show.",r:"For fans of the TV show or of drag racing specifically; most other racing fans can skip it.",b:"Physical PS4 disc from GameMill, 2021 (UPC 856131008497); distinct from the census's Street Outlaws: The List.",p:"WAIT cheap."},
{t:"Baja: Edge of Control HD",s:"THQ Nordic's 2017 remaster of the 2008 off-road racer covers the Baja 1000 desert race with trucks, buggies and motorcycles across long rally stages.",w:"It is a rare long-distance off-road racer with challenging terrain and vehicle damage that rewards patience.",c:"Dated visuals and handling, punishing physics and long stretches of similar desert environments make it a hard sell today.",r:"For off-road racing enthusiasts who enjoy endurance events; most players will prefer modern racers.",b:"Physical PS4 disc from THQ Nordic, 2017, distributed physically and digitally on a global basis.",p:"WAIT cheap."},
{t:"The Smurfs 2: Prisoner of the Green Stone",s:"Microids and OSome Studio's 2023 3D platformer sends the Smurfs to rescue Papa Smurf from a mysterious green stone, using a backpack device with combat and traversal abilities.",w:"It improves on Mission Vileaf, with more variety in characters and environments, and suits young platformer fans.",c:"Short and simple, with basic combat, little challenge and a campaign most adults will finish in a few sittings.",r:"A charming family platformer for Smurfs fans; a light rental-weight game for others.",b:"Physical PS4 retail edition from Microids, December 2023, released in North America alongside the European release.",p:"MAYBE cheap."},
{t:"Cobra Kai: The Karate Kid Saga Continues",s:"Flux Games' 2020 beat 'em up lets players choose the Cobra Kai or Miyagi-Do side, with playable characters from the Netflix series and a story set around the All Valley tournament.",w:"It is a fan-pleasing brawler with both dojos' storylines and characters, plus local co-op.",c:"Repetitive combat, poor performance and a short campaign; the presentation is budget.",r:"For Cobra Kai fans who want a couch co-op brawler with the show's characters; otherwise skippable.",b:"Physical PS4 disc from GameMill, October 2020 (UPCs 856131008251 and 856131008473), sold at major retailers.",p:"WAIT cheap."},
{t:"Real Farm",s:"Triangle Studios' 2017 farming simulator puts players in charge of a farm, growing crops, raising livestock and expanding fields with licensed tractors.",w:"It is a simpler alternative to Farming Simulator with a career mode that guides newcomers.",c:"Clunky controls, basic visuals and repetitive tasks; it trails Farming Simulator in depth and polish.",r:"Only for completionists of farming sims; Farming Simulator is the better choice.",b:"Physical and digital PS4 release from SOEDESCO, 2017, published alongside Xbox One and PC versions.",p:"WAIT cheap."},
{t:"The House of the Dead Remake",s:"MegaPixel Studio's 2022 remake of Sega's 1996 rail shooter rebuilds the Curien Mansion outbreak with updated visuals, a horde mode and branching paths.",w:"It preserves the arcade classic's branching routes and cheesy horror, with a horde mode that adds hundreds of zombies on screen.",c:"Very short, aiming with a controller is imprecise, and the remake's visuals are only modest.",r:"A brief, nostalgic arcade blast best with a friend; worth owning cheaply.",b:"Physical PS4 Limidead Edition from Microids, December 2022, sold as the boxed retail version of the game.",p:"MAYBE cheap."},
{t:"Tiny Tina's Wonderlands",s:"Gearbox's 2022 fantasy spin-off of Borderlands lets players explore a tabletop world run by Tiny Tina, with spells, melee weapons and a customizable class system.",w:"It is a fresh, funny take on the Borderlands loot-shooter formula, with an overworld and strong co-op.",c:"Repetitive endgame, uneven humor and familiar shooting; the PS4 version trails current-gen visually.",r:"A great co-op shooter for Borderlands fans looking for a lighter fantasy adventure.",b:"Physical PS4 disc from 2K, March 2022; the PS4 disc of the Standard Edition also plays on PS5.",p:"BUY cheap."},
{t:"Sniper Elite 5",s:"Rebellion's 2022 Sniper Elite follows Karl Fairburne through occupied France in 1944, with large open-ended maps, the X-ray kill cam and invasion multiplayer.",w:"It is the series' best entry, with excellent maps, rich stealth options and full co-op.",c:"Story is forgettable, and AI behavior can be predictable; PS4 performance trails PS5.",r:"A satisfying sniper sandbox that rewards patience and planning; a strong shelf pick.",b:"Physical PS4 disc from Rebellion, May 2022, sold as a standard retail release.",p:"BUY cheap."},
{t:"Stubbs the Zombie in Rebel Without a Pulse",s:"Aspyr's 2021 port of Wideload's 2005 cult game puts players in control of zombie Stubbs, rampaging through a retro-futurist 1950s city with gut grenades and possession.",w:"It is a weird, funny cult classic built on the Halo engine, with an excellent cover-song soundtrack.",c:"Dated mechanics and level design; the port is faithful but not modernized.",r:"A fun, funny nostalgia piece for collectors of cult classics who enjoy mid-2000s action design.",b:"Physical PS4 edition from THQ Nordic, October 2021, available worldwide on PS4, Xbox One and Switch.",p:"MAYBE cheap."},
{t:"Psychonauts 2",s:"Double Fine's 2021 sequel follows psychic agent Raz into the minds of colleagues and villains, with vivid, imaginative levels based on each character's psychology.",w:"It is one of the best 3D platformers of its generation, with creative level design and a heartfelt story about mental health.",c:"Combat is the weakest part, and some players may find the platforming easy.",r:"An essential, creative adventure that respects your time; a top-tier PS4 pick.",b:"Physical PS4 Motherlobe Edition released October 2022 at retailers for $69.99, after the 2021 digital launch.",p:"TOP-TIER buy."},
{t:"Monster Jam: Steel Titans 2",s:"Rainbow Studios' 2021 sequel lets players drive licensed Monster Jam trucks in stadium events and open-world areas, with freestyle tricks and races.",w:"It improves on the first game with open environments and more trucks, offering a satisfying arcade monster truck experience.",c:"Handling is tricky to master, events repeat often, and the presentation is modest even by licensed-game standards.",r:"A good monster truck game for fans of the show; others may quickly lose interest.",b:"Physical PS4 editions from THQ Nordic, March 2021, released for PS4, Xbox One, Switch and PC.",p:"WAIT cheap."},
{t:"Monster Jam Crush It",s:"GameMill's 2016 monster truck game lets players drive licensed Monster Jam trucks in arenas, freestyle events and destruction challenges.",w:"It is the first Monster Jam game on PS4, with a range of licensed trucks.",c:"Weak physics, limited content and dated presentation; Steel Titans games are much better.",r:"For franchise completionists only; the Steel Titans games are far better monster truck options.",b:"Physical PS4 disc from GameMill, 2016, sold at select retailers for $29.99.",p:"WAIT cheap."},
{t:"Family Feud",s:"Ubisoft's 2020 version of the TV game show lets families compete by guessing the top survey answers, with customizable avatars and online play.",w:"It recreates the show's format well, and it works as an accessible local party game.",c:"Limited content and repeats; online needs servers and the presentation is simple.",r:"A party game for fans of the show; best with family groups.",b:"Physical PS4 release from Ubisoft, 2020; retail copies were sold only in the United States and Canada.",p:"WAIT cheap."},
{t:"Sniper Ghost Warrior Contracts 2",s:"CI Games' 2021 sniping sequel moves to a Middle Eastern setting, with long-range shots over 1,000 meters across five large sandbox regions.",w:"It is a big improvement over the first Contracts game, with satisfying long-range shooting and open-ended maps.",c:"AI and story are weak, and the PS4 version runs at a lower resolution than current-gen versions.",r:"A good, focused sniping game for genre fans who enjoy long shots; average for everyone else.",b:"Physical PS4 edition from CI Games, June 2021; library records describe it as a single Blu-ray disc.",p:"MAYBE cheap."},
{t:"Ghostbusters: Spirits Unleashed",s:"IllFonic's 2022 asymmetric multiplayer game pits four Ghostbusters against one player-controlled ghost in haunted locations, with Ray Stantz and Winston Zeddemore voiced by Dan Aykroyd and Ernie Hudson at the Firehouse hub.",w:"It is the most faithful modern Ghostbusters game, with proton-pack wrangling, trap teamwork and a ghost side that feels mischievous rather than murderous.",c:"Built around online matchmaking; bots fill in offline, but the experience is far weaker without people, and content variety is limited.",r:"A fun, fan-pleasing party game while players and servers remain; solo players will run out of reasons to play fast.",b:"Physical PS4 release from IllFonic with physical-edition bonuses sold at Target; later Ecto Edition releases are packaging of the same game.",p:"MAYBE cheap."},
{t:"The Knight Witch",s:"Super Awesome Hyper Dimensional Mega Team's 2022 Metroidvania shoot 'em up follows Rayne, a flying witch, through an underground city, combining exploration with bullet-hell combat and a spell-card deck.",w:"It mixes a twin-stick shooter and Metroidvania in a way few games try, with gorgeous hand-drawn art and a Link system tied to story choices.",c:"Map navigation can be confusing, the difficulty spikes in later bosses, and card-based spells add randomness some players dislike.",r:"A creative, charming hybrid worth owning for shmup and Metroidvania fans who want something fresh.",b:"Physical PS4 Deluxe Edition from Fireshine Games, the only physical version, sold at retail with bonus content.",p:"BUY cheap."},
{t:"ELEX II",s:"Piranha Bytes' 2022 open-world RPG returns to Magalan as Jax unites factions against an alien invasion, with jetpack traversal, faction choices and a mix of science fiction and fantasy.",w:"It keeps Piranha Bytes' distinctive old-school RPG style, with real faction consequences and a large, handcrafted world to explore by jetpack.",c:"Clunky combat, dated animations, rough performance on PS4 and an early difficulty curve that punishes new players.",r:"For players who enjoy janky European RPGs with real freedom; others will bounce off its rough edges quickly.",b:"Physical PS4 standard and Collector's Edition from THQ Nordic, March 2022; the collector's box is packaging only.",p:"WAIT cheap."},
{t:"Transformers Galactic Trials",s:"3DClouds and Outright Games' 2024 racing and shooting game lets players drive Autobots and Decepticons through races and battles, transforming between vehicle and robot modes on the track.",w:"It is a light, accessible licensed racer that suits younger Transformers fans who want recognizable characters and simple combat.",c:"Shallow racing and repetitive events; presentation is modest and the game offers little challenge for experienced players.",r:"A family pick for young Transformers fans; racing enthusiasts will find better games elsewhere.",b:"Physical PS4 disc from Outright Games, October 2024; The Game Collection lists it as a physical PS4 disc.",p:"WAIT cheap."},
{t:"Persona 5: Dancing in Starlight",s:"Atlus's 2018 rhythm game spin-off has the Phantom Thieves dancing in a dream-like Velvet Room to remixes of Persona 5's soundtrack, with short social interactions between songs.",w:"Persona 5's music is outstanding, and the remixes and fully animated dance routines make it a stylish celebration for fans.",c:"The song list is small, many tracks are remixes rather than originals, and the story content is light.",r:"A fun, short rhythm game for Persona fans; casual rhythm players may find it slight.",b:"Standalone physical PS4 release from Atlus, December 2018, also sold within the Endless Night Collection.",p:"MAYBE cheap."},
{t:"Samurai Warriors 5",s:"Omega Force's 2021 reboot of Samurai Warriors retells the Sengoku period through Nobunaga Oda and Mitsuhide Akechi, with a new ink-wash art style and Hyper attacks.",w:"Its fresh art style and focused story give the series new life, and the combat is fast, flashy and satisfying.",c:"The roster is smaller than earlier entries, missions repeat, and the story focuses on a narrower set of characters.",r:"A strong musou entry for fans who want a tighter story and good-looking battles.",b:"Physical PS4 Standard Edition from Koei Tecmo, July 2021, plus Treasure Box and Collector's Edition packaging.",p:"BUY cheap."},
{t:"Star Ocean: The Divine Force",s:"tri-Ace's 2022 sci-fi RPG follows captain Raymond Lawrence and princess Laeticia Aucerius on an underdeveloped planet, with the D.U.M.A. drone powering flight, traversal and combat.",w:"D.U.M.A. makes exploring large open areas fun, and the combat is fast and flexible with a choice of two protagonists.",c:"Uneven story pacing, dated visuals and a rough PS4 version; character animation lags behind modern RPGs.",r:"A flawed but enjoyable RPG for Star Ocean fans who value fast combat and exploration.",b:"Physical PS4 Standard Edition from Square Enix, October 2022; Target lists it as a physical-format PS4 release.",p:"MAYBE cheap."},
{t:"Trek to Yomi",s:"Flying Wild Hog's 2022 side-scrolling samurai action game follows Hiroki in black-and-white cinematic style inspired by Akira Kurosawa, through a journey from his village into the Buddhist underworld of Yomi.",w:"Its film-like camera work and striking monochrome visuals make it one of the most atmospheric action games of its generation.",c:"Combat is simple, puzzles are thin, and the game is short; some fixed camera angles hurt readability.",r:"A beautiful, compact samurai film to play; best for players who value style and respect for time.",b:"Physical PS4 release from Devolver Digital, May 2023, after the 2022 digital launch; PAL copies list one game disc.",p:"BUY cheap."},
{t:"Fate/Samurai Remnant",s:"Omega Force's 2023 action RPG sets a Holy Grail War in Edo-era Japan, with swordsman Miyamoto Iori and his Servant Saber fighting other Masters in the Waxing Moon Ritual.",w:"It is a strong Fate game for newcomers, with a self-contained story, a beautiful Edo setting and fast action combat.",c:"Long dialogue scenes, repetitive side content, and a heavy reliance on Fate lore that may confuse newcomers.",r:"A polished action RPG for Fate fans and samurai drama lovers alike.",b:"Physical PS4 release from Koei Tecmo, September 2023, including the Treasure Box collector's edition.",p:"MAYBE cheap."},
{t:"Planet Coaster: Console Edition",s:"Frontier's 2020 console version of Planet Coaster lets players build theme parks with detailed coaster design, scenery editors and park management.",w:"It is the most powerful park builder on PS4, with an excellent coaster editor and lots of creative freedom.",c:"Complex controls and menus, steep learning curve and some performance drops in large parks on base PS4.",r:"A great creative toy for builders; patience is rewarded with spectacular parks.",b:"Physical PS4 disc from Frontier, November 2020; UK distribution was handled by Sold Out.",p:"BUY cheap."},
{t:"The Dungeon of Naheulbeuk: The Amulet of Chaos",s:"Artefacts Studio's 2020 comedic tactics RPG follows a hapless party of adventurers through a dungeon, based on the French audio saga by John Lang.",w:"It delivers a funny, self-aware fantasy parody with solid turn-based tactics and a cast of bickering misfits.",c:"Humor translated from French doesn't always land, combat can be slow, and difficulty spikes appear in later fights.",r:"A charming tactics game for fans of fantasy parody and party banter.",b:"Physical PS4 release in North America from GS2 Games, June 2021, alongside a Switch release.",p:"MAYBE cheap."},
{t:"Star Ocean: The Second Story R",s:"Gemdrops' 2023 remake of the classic 1998 RPG combines 2D sprites with 3D environments, following Claude and Rena with the series' Private Actions and real-time combat.",w:"It is a superb remake with rebuilt visuals, a remastered soundtrack and many quality-of-life improvements.",c:"Its story is very classic in structure, and crafting systems can be overwhelming for newcomers.",r:"A top-tier JRPG remake that respects both newcomers and veterans with sensible modern conveniences and fast battles.",b:"Physical PS4 Standard and Collector's Edition from Square Enix, November 2023; the PS4 disc includes a PS5 upgrade.",p:"STRONG buy."},
{t:"The Last Stand: Aftermath",s:"Con Artist Games' 2021 roguelite zombie survival game puts infected survivors on a journey through a post-apocalyptic landscape, with each run carrying over upgrades and knowledge.",w:"It combines tense scavenging and shooting with a solid roguelite structure, where each survivor's death feeds future runs.",c:"Repetitive environments, limited variety in later runs, and an inventory system that can feel cramped.",r:"A good, bite-sized survival roguelite for zombie fans who like short runs that build toward a longer journey.",b:"Physical PS4 release from Merge Games in the UK, November 2021 (EAN 5060264376704).",p:"MAYBE cheap."},
{t:"Dolmen",s:"Massive Work Studio's 2022 sci-fi Souls-like casts you as a soldier on the planet Revion Prime, with ranged and melee combat and a system that burns energy to heal.",w:"It offers a gothic sci-fi setting and unusual energy-based healing that make it stand out from other Souls-likes.",c:"Weak level design, stiff combat and a forgettable story; performance and balance are inconsistent.",r:"Only for players hungry for more Souls-likes after the genre leaders; better options exist at similar prices.",b:"Physical PS4 release from Koch Media/Prime Matter, May 2022, including a Day One Edition in Europe.",p:"WAIT cheap."},
{t:"Sword Art Online Last Recollection",s:"Aquria and Bandai Namco's 2023 action RPG covers the War of Underworld arc of Sword Art Online, with Kirito, Alice and allies fighting in large party battles.",w:"It is a fan-focused conclusion to the Alicization saga, with a large cast and fast party combat.",c:"Repetitive quests, weak visuals and a story that assumes knowledge of the anime.",r:"Strictly for Sword Art Online fans who want the Underworld arc in game form.",b:"Physical PS4 release from Bandai Namco, October 2023 (UPC 722674121972), sold at Target and other retailers.",p:"WAIT cheap."},
{t:"Mercenaries Rebirth: Call of the Wild Lynx",s:"Rideon's 2022 tactical RPG continues the Mercenaries series with grid-based battles, class changes and a fantasy story about a wild mercenary girl named Lynx.",w:"It is a classic-style tactics game for fans of old-school SRPGs, with deep class growth and challenging battles.",c:"Low-budget presentation, slow pacing and basic storytelling, with menus and an interface that feel dated by modern standards.",r:"For dedicated tactics fans who enjoy classic design and deep class growth.",b:"Physical PS4 release from PM Studios, July 2023, following the 2022 digital launch.",p:"WAIT cheap."},
{t:"Poker Club",s:"Ripstone's 2020 poker game focuses on Texas Hold'em with lifelike tables, online play and a career progression through tournaments.",w:"It is a polished poker game on PS4 with good presentation and online ranked tables.",c:"Online-dependent, with little to do offline; long-term playability depends entirely on whether servers and players remain.",r:"For poker fans only; its value is tied to the online player base.",b:"Physical PS4 disc from Ripstone, September 2021, in the UK and Europe; online play is required.",p:"WAIT cheap."},
{t:"Hotel Transylvania: Scary Tale Adventure",s:"Drakhar Studio and Outright Games' 2022 action adventure has Mavis and Drac journeying through storybook worlds to rescue friends trapped in a magical book.",w:"It is a gentle licensed adventure for young fans, with simple puzzles, combat and colorful storybook levels.",c:"Short, easy and repetitive, with simple combat and puzzles; there is little appeal outside its young target audience.",r:"A pleasant kids' adventure for fans of the films; adults can skip it.",b:"Physical PS4 Blu-ray from Outright Games, March 2022, sold as Hotel Transylvania: Scary-Tale Adventures (UPC 819338021409).",p:"WAIT cheap."},
{t:"Train Sim World 2",s:"Dovetail Games' 2020 train simulator offers detailed operation of trains across US, UK and German routes, with a Rush Hour mode and expanded route editor.",w:"It is a deep, realistic train sim with detailed cab controls and a steady stream of routes.",c:"Requires patience and learning; much of the content is paid DLC, and the console interface is cumbersome.",r:"An excellent relaxing sim for rail enthusiasts who enjoy procedure; not a good fit for casual players.",b:"Physical PS4 Collector's Edition from Maximum Games, 2020, sold with extra routes at retail.",p:"MAYBE cheap."},
{t:"Nickelodeon All-Star Brawl",s:"Ludosity and Fair Play Labs' 2021 platform fighter brings together Nickelodeon characters like SpongeBob, Danny Phantom and Leonardo in Smash-style arenas.",w:"It has surprisingly solid fighting fundamentals and a fun roster for Nickelodeon fans.",c:"No voice acting, thin single-player and a small roster at launch; the sequel improves almost everything.",r:"A fun party fighter for fans, but the sequel is the better buy.",b:"Physical PS4 disc from GameMill, October 2021 (UPC 856131008534); the original game, not All-Star Brawl 2.",p:"WAIT cheap."},
{t:"The Golf Club 2019 Featuring PGA Tour",s:"HB Studios' 2018 golf game is the first in the series with an official PGA Tour license, offering a career mode, licensed courses and a powerful course creator.",w:"Its course designer and community courses give it long-term variety, while the swing mechanics reward precision.",c:"Presentation is modest and licensed content is limited; the year-titled name ties it to an annual-sports format.",r:"A good golf sim for fans who like realistic swings and community courses.",b:"Physical PS4 disc from 2K/HB Studios, November 2018 (UPC 710425574795), after an August 2018 digital launch.",p:"MAYBE cheap."},
{t:"New Super Lucky's Tale",s:"Playful's 2019 3D platformer follows Lucky the fox through colorful worlds to save the Book of Ages, a reworked version of the original Super Lucky's Tale.",w:"It is a cheerful, polished platformer with tight controls and many collectibles, perfect for young or casual players.",c:"Easy and safe level design, with little challenge for experienced platformer fans.",r:"A charming family platformer that respects your time, with bright worlds and forgiving checkpoints for younger players.",b:"Physical PS4 release from Playful in the Americas, November 2020; PQube released it physically in Europe.",p:"BUY cheap."},
{t:"Session: Skate Sim",s:"crea-ture Studios' 2022 skateboarding simulator uses two analog sticks to control each foot, with real-world street spots, physics-heavy tricks and a video editor.",w:"It is the most realistic skateboarding game available, rewarding practice with a deep, satisfying trick system.",c:"Steep learning curve, sparse goals and limited structure; its realism can frustrate players expecting Tony Hawk.",r:"For dedicated skating fans who want realism; casual players should look elsewhere.",b:"Physical PS4 disc from Nacon/Maximum Games, September 2022 (UPC 814290018054); Target lists it as physical.",p:"MAYBE cheap."},
{t:"RiMS Racing Sim",s:"RaceWard Studio's 2021 motorcycle sim offers detailed superbike racing with component management, where players install and tune parts between races.",w:"It is a unique motorcycle sim that models mechanical parts and their wear, aimed at bike enthusiasts.",c:"Difficult handling, small bike roster and limited content; the presentation is modest.",r:"A niche sim for dedicated motorcycle fans who like tinkering with parts between races as much as riding.",b:"Physical PS4 disc from Nacon, August 2021 (EAN 3665962008685), sold through European retailers.",p:"WAIT cheap."},
{t:"Miraculous: Rise of the Sphinx",s:"Magic Pockets and GameMill's 2022 action adventure follows Ladybug and Cat Noir defending Paris from Hawk Moth's akumatized villains, including the Sphinx.",w:"It is a simple, colorful licensed adventure for young fans of the animated series.",c:"Repetitive combat and missions, modest presentation and very little challenge for anyone beyond its young audience.",r:"Only for young fans of the Miraculous show; other players can comfortably skip this licensed adventure.",b:"Physical PS4 Blu-ray from GameMill, 2022, with a PS5 upgrade; distinct from Paris Under Siege.",p:"WAIT cheap."},
{t:"Tchia",s:"Awaceb's 2023 open-world adventure is set on a tropical archipelago inspired by New Caledonia, where Tchia can soul-jump into animals and objects and play a ukulele.",w:"It is a joyful, creative open world, with soul-jumping traversal and a culturally specific setting rarely seen in games.",c:"Combat is weak, the story can feel thin, and PS4 performance is limited compared to PS5.",r:"A refreshing open-world game with creativity and charm that rewards curiosity, play and simply wandering around.",b:"Physical PS4 Oléti Edition from Kepler Interactive, distributed by Maximum Games, July 2023.",p:"BUY cheap."},
{t:"Five Nights at Freddy's: Into the Pit",s:"Mega Cat Studios' 2024 pixel-art horror adventure follows Oswald, who discovers a ball pit that sends him back to 1985 at Jeff's Pizza, adapting the Fazbear Frights story.",w:"It is a strong 2D horror adventure with good puzzles and atmosphere, praised as one of the best Five Nights at Freddy's games.",c:"Short, with some frustrating chase sequences and a story that leans on franchise lore.",r:"A good horror adventure for fans of the series and of retro pixel art.",b:"Physical PS4 edition from iam8bit and Mega Cat Studios, June 2025, with the main game on disc.",p:"MAYBE cheap."},
{t:"Pro Fishing Simulator",s:"Sanuk Games and Bigben's 2018 fishing simulator offers competitive bass fishing across lakes, with boats, lures and tournament play.",w:"It is a fishing sim for players who want simple tournament progression on PS4.",c:"Dated visuals, clunky controls and little content; it was poorly received at launch.",r:"For fishing completionists only; theHunter-style alternatives and better fishing games already exist on PS4.",b:"Physical PS4 copy from Bigben Interactive, 2018 (US EAN 814290014629), with European editions as well.",p:"WAIT cheap."},
{t:"Digimon Survive",s:"Hyde and Bandai Namco's 2022 visual novel tactics game follows Takuma and classmates stranded in a strange world, with moral choices shaping Digimon evolution and endings.",w:"It is a darker, story-heavy Digimon game, with branching routes and memorable character arcs.",c:"Very slow pacing, long text sections and simple tactical battles; it is mostly a visual novel.",r:"A rewarding, surprisingly dark story game for Digimon fans who are comfortable reading long visual novel scenes.",b:"Physical PS4 Blu-ray from Bandai Namco America, July 2022; some European copies were code-in-box, so check the disc.",p:"MAYBE cheap."},
{t:"Star Trek Prodigy: Supernova",s:"Tessera Studios and Outright Games' 2022 puzzle platformer follows Dal and Gwyn from the animated series, using teamwork and two-player co-op to solve puzzles.",w:"It is a gentle licensed co-op game for families, with clear puzzles and a friendly tone.",c:"Short, repetitive and easy, with simple puzzles and little reason to replay once the story is finished.",r:"A good family co-op game for young Star Trek fans who watched the animated series.",b:"Physical PS4 Blu-ray from Outright Games, October 2022, with a PS5 upgrade noted on the box.",p:"WAIT cheap."},
{t:"Who Wants to be a Millionaire?",s:"Microids' 2020 quiz game recreates the TV show with lifelines, question ladders and local and online multiplayer.",w:"It is a faithful recreation of the show's tension, and works well as a party game for families.",c:"Questions repeat quickly, presentation is basic, and the overall content is thin for anyone playing alone.",r:"A quick, light party game for fans of the show to play with family on game nights.",b:"Physical PS4 Blu-ray from Microids, 2020; PAL copies list one game disc in collector data.",p:"WAIT cheap."},
{t:"REYNATIS",s:"FuRyu and NIS America's 2024 urban action RPG is set in a Shibuya where wizards are persecuted, following Marin Kirizumi as he fights the authorities and the mysterious EMMA.",w:"It has a stylish urban setting and an interesting story about magic and oppression in modern Tokyo.",c:"Performance problems, repetitive missions and unpolished combat limit its appeal, especially on base PS4 hardware.",r:"A flawed but interesting urban fantasy RPG for fans of quirky Japanese action games.",b:"Physical PS4 Deluxe Edition from NIS America, September 2024 (UPC 810100863739), sold at Target and other retailers.",p:"WAIT cheap."},
{t:"Nick Jr. Party Adventure",s:"Outright Games' 2024 preschool party game brings together favorite Nick Jr. characters for simple mini-games and gentle adventures aimed at very young children.",w:"It is a child-first game with simple controls and no failure, designed for young players and parents.",c:"Very little challenge or depth; adults playing alone will find nothing to do.",r:"Only for households with preschool fans of Nick Jr. shows; everyone else should skip it entirely.",b:"Physical PS4 disc from Outright Games, October 2024 (UPC 819338024424), listed by The Game Collection as physical.",p:"WAIT cheap."},
{t:"Tintin Reporter: Cigars of the Pharaoh",s:"Pendulo Studios and Microids' 2023 3D adventure adapts Hergé's 1934 Tintin album, following Tintin and Snowy from Egypt onward through exploration, puzzles and stealth.",w:"It captures Hergé's art style in 3D, with a faithful adaptation of a classic album.",c:"Puzzles are simple, stealth is clunky and the performance is rough in places.",r:"A good choice for Tintin fans who want to explore Hergé's world; others may find it average.",b:"Physical PS4 Limited Edition from Microids, November 2023, plus PAL standard and Collector's Edition.",p:"MAYBE cheap."},
{t:"Smile For Me",s:"LimboLane's 2019 point-and-click adventure takes place in the Habitat, a creepy facility run by Dr. Habit, where players nod or shake their heads to answer and help residents smile.",w:"It is a strange, memorable surrealist adventure with charming characters and multiple endings.",c:"Short, with odd pacing and puzzles that can be obscure; the tone may be unsettling for some.",r:"A unique, cult indie adventure worth owning for fans of offbeat narrative games.",b:"Physical PS4 edition from Serenity Forge, including a Collector's Edition, after the original digital release.",p:"BUY cheap."},
{t:"Story of Seasons: Pioneers of Olive Town",s:"Marvelous's farming life sim lets players develop a farm in Olive Town, with crafting machines, animals, friendships and marriage candidates.",w:"It is a relaxing farm sim with deep crafting and a big map, and the PS4 version adds performance improvements.",c:"Repetitive crafting, a slow start and weaker character writing than Friends of Mineral Town.",r:"A cozy farm sim for genre fans who want a long-lasting routine.",b:"Physical PS4 release from XSEED/Marvelous, July 2022; distinct from Story of Seasons: Friends of Mineral Town.",p:"MAYBE cheap."},
{t:"Trolls Remix Rescue",s:"GameMill's 2023 platformer based on the DreamWorks Trolls films follows Poppy and Branch through musical worlds, with co-op and songs from the films.",w:"It is a cheerful licensed platformer for young fans, with familiar music and easy co-op play.",c:"Short and simple, with little challenge for older players and limited reasons to return after finishing.",r:"A light, family-friendly licensed game for young Trolls fans and parents playing together in co-op.",b:"Physical PS4 Blu-ray from GameMill, 2023, sold as DreamWorks Trolls Remix Rescue.",p:"WAIT cheap."},
{t:"Farming Simulator 15",s:"Giants Software's 2015 farming sim was the series' first on PS4, adding forestry and wood-cutting machines to crop and livestock farming.",w:"It marks the start of the series on PS4, with forestry and a wide selection of licensed machines.",c:"Dated presentation, a slow pace and clunky controller handling; later Farming Simulator games are deeper.",r:"For series completionists only; Farming Simulator 22 is the better option for most farm-sim players.",b:"Physical PS4 disc from Focus Home/Maximum Games, May 2015; the Complete Edition is packaging of the same game.",p:"WAIT cheap."},
{t:"Override 2: Super Mech League",s:"Modus Games' 2020 mech brawler pits giant robots against each other in arenas, with a league mode, customization and local and online multiplayer.",w:"It is a fun, accessible mech brawler for local play, with a varied roster and the Ultraman Deluxe guest characters.",c:"Shallow single-player content, repetitive matches and limited depth once you have tried every mech.",r:"Good party fun for mech fans with friends on the couch, but there is little long-term depth.",b:"Physical PS4 release from Modus Games as the Ultraman Deluxe Edition, which is packaging of the same game.",p:"WAIT cheap."},
{t:"Under Night In-Birth Exe:Late[st]",s:"French-Bread and Arc System Works' 2017 anime fighter refines the Under Night In-Birth series with the GRD Grind Grid system, a large roster and tutorials.",w:"It is a deep, rewarding fighter with great sprite work, strong tutorials and the distinctive GRD system.",c:"Hard to master and online community is small; its successor Sys:Celes improves it.",r:"A good fighting game for anime fighter fans, though Sys:Celes is the better buy.",b:"Physical PS4 release via PQube in Europe and Aksys in North America, 2018; distinct from Under Night In-Birth II.",p:"MAYBE cheap."},
{t:"Tin Hearts",s:"Rogue Sun's 2023 puzzle game has players guiding marching toy soldiers through a Victorian toymaker's house, adjusting objects to route them to their goal.",w:"It is a charming Lemmings-like puzzle game with a touching story about inventor Albert Butterworth's family.",c:"Slow pacing and occasionally fiddly object placement with a controller can make later puzzles feel tedious.",r:"A lovely, thoughtful puzzle game that rewards patience and has real heart in its family story.",b:"Physical PS4 edition from Wired Productions with a reversible inlay and sticker sheet.",p:"BUY cheap."},
{t:"Loop8: Summer of Gods",s:"Sieg Games and Marvelous's 2023 time-loop RPG is set in the 1980s Japanese town of Ashihara, where a boy from an orbital station fights the Kegai and builds friendships.",w:"It has an interesting premise and beautiful rural setting, with character AI that reacts to your choices.",c:"Repetitive, slow and weakly paced; combat is simple and the systems are confusing.",r:"A flawed experiment for fans of social sims willing to accept rough edges.",b:"Physical PS4 Celestial Edition and standard release from XSEED/Marvelous, June 2023, alongside Xbox One and Switch.",p:"WAIT cheap."},
{t:"Puyo Puyo Tetris 2",s:"Sega's 2020 sequel to the puzzle crossover adds a new adventure mode, Skill Battle mode with RPG-style abilities, and more ways to play Puyo Puyo and Tetris together.",w:"It is a great, accessible competitive puzzle game with strong local multiplayer and lots of modes.",c:"It is close to the original, and online play depends on servers.",r:"A top-tier party puzzle game for local multiplayer, with enough single-player modes to stay useful solo.",b:"Physical PS4 Launch Edition from Sega, December 2020, with item cards; the edition is packaging only.",p:"BUY cheap."},
{t:"Gloomhaven: Mercenaries Edition",s:"Flaming Fowl's 2023 console version of the digital Gloomhaven adapts the board game's card-driven tactics, where each turn uses cards for both movement and attacks.",w:"It is a faithful adaptation of one of the most-praised board games, with deep tactical combat and campaign progression.",c:"Steep learning curve, slow pacing and a complex interface on controller make the first hours demanding.",r:"A rewarding tactics game for patient strategy fans who enjoy the board game's careful card play.",b:"Physical PS4 disc from Twin Sails Interactive, with retail by Nighthawk Interactive, September 2023.",p:"MAYBE cheap."},
{t:"Where the Heart Leads",s:"Armature Studio's 2021 narrative adventure follows Whit Anderson, who falls into a sinkhole while saving his dog and relives his life through surreal memories.",w:"It is an emotional, choice-driven life story with real consequences and beautiful presentation.",c:"Slow, with little gameplay beyond choices and walking; long by narrative game standards.",r:"A rewarding, thoughtful story game for players who enjoy narrative choices with lasting consequences.",b:"Physical PS4 edition by Perp Games, July 2021 in Europe and September 2021 in North America.",p:"MAYBE cheap."},
{t:"Poison Control",s:"Nippon Ichi's 2021 action game sends a girl in Hell, paired with the demon Poisonette, to purify toxic Mire with a third-person shooter style and dating-sim elements.",w:"It is a quirky, original game with colorful design and a fun mix of shooting and character stories.",c:"Repetitive levels and simple combat; the story is weird even by NIS standards.",r:"A cheerful oddball game for fans of Nippon Ichi's quirky output who want something different.",b:"Physical PS4 release from NIS America, April 2021 (UPC 810023036647), sold at Target and other retailers.",p:"WAIT cheap."},
{t:"Monster Truck Championship",s:"Teyon and Nacon's 2020 monster truck sim offers racing, freestyle and destruction events with physics-driven handling and truck upgrades.",w:"It is the most realistic monster truck game on PS4, with demanding handling and a career mode.",c:"Steep learning curve, modest presentation and limited content variety across its career events.",r:"Good for monster truck enthusiasts who want sim handling; others may prefer the arcade Steel Titans games.",b:"Physical PS4 copy from Nacon, November 2020 (EAN 3665962000917), sold sealed through European retailers.",p:"WAIT cheap."},
{t:"KONOSUBA - God's Blessing on this Wonderful World! Love For These Clothes Of Desire!",s:"MAGES' visual novel based on the KonoSuba comedy series has Kazuma and his party take on fashion-themed adventures in an original story, with choices and endings.",w:"It is a faithful, funny adaptation with the anime's voice cast and characters, aimed at KonoSuba fans.",c:"Mostly text and choices; little gameplay, and its humor depends on knowing the series.",r:"Only for KonoSuba fans who enjoy visual novels and already know the characters and their humor.",b:"Physical PS4 release from PQube, February 2024, also physically released on Switch.",p:"WAIT cheap."},
{t:"DreamWorks Dragons: Legends of the Nine Realms",s:"Outright Games' 2022 action adventure follows the young dragon Thunder and friends from the animated series The Nine Realms, solving puzzles and fighting enemies in co-op.",w:"It is a gentle licensed adventure for young fans with simple puzzles and two-player co-op.",c:"Short, easy and repetitive, with little appeal outside its young target audience and limited replay value.",r:"A good family co-op game for young fans of the series to play alongside a parent.",b:"Physical PS4 Blu-ray from Outright Games, September 2022 (UPC 819338022178); the EU box drops the DreamWorks name.",p:"WAIT cheap."},
{t:"Life in Willowdale: Farm Adventures",s:"Mindscape's farm life sim lets players run a countryside farm, caring for animals, growing crops and building friendships in the village of Willowdale.",w:"It is a gentle, approachable farm sim for younger or casual players who want a relaxed routine.",c:"Shallow systems and repetitive tasks compared with genre leaders like Stardew Valley or Story of Seasons.",r:"A cozy family pick for younger players; dedicated farm-sim fans will want more depth and variety.",b:"Physical PS4 release from Mindscape, released physically and digitally on Switch, PS4, PS5 and Steam.",p:"WAIT cheap."},
{t:"Metal Tales: Overkill",s:"Zerouno Games' heavy metal roguelite shooter sends guitar-wielding metalheads through hordes of enemies in procedurally arranged levels, with riffs as weapons.",w:"Its heavy metal theme and soundtrack give the roguelite shooter a unique and fun personality.",c:"Repetitive levels, simple enemy variety and a rough presentation hold back an otherwise fun concept.",r:"A fun novelty for metal fans who enjoy twin-stick roguelites and loud guitar soundtracks.",b:"Physical PS4 release from Funstock, August 2023 (EAN 5056607400458), distributed in the UK by Centresoft.",p:"WAIT cheap."},
{t:"Endling - Extinction is Forever",s:"Herobeat Studios' 2022 side-scrolling adventure casts you as the last mother fox, protecting and feeding cubs in a world devastated by humans.",w:"It is a moving, beautiful game with a strong environmental message and tense survival moments.",c:"Short, repetitive scavenging and emotionally heavy themes that may upset younger players.",r:"A memorable, emotional adventure worth owning for its atmosphere and its strong environmental message.",b:"Physical PS4 release from HandyGames, July 2022, launched both physically and digitally.",p:"BUY cheap."},
{t:"V-Rally 4",s:"Kylotonn and Bigben's 2018 revival of the V-Rally series offers rally, hillclimb, buggy, extreme-khana and V-Rally Cross events with a career mode.",w:"It has a broad range of off-road events and challenging handling, a solid choice for rally fans.",c:"Handling can be twitchy, presentation is average, and the career content repeats events often.",r:"A decent rally game for genre fans who want variety; DiRT Rally offers deeper handling.",b:"Physical PS4 disc distributed by Maximum Games (EAN 3499550366297), September 2018; an Ultimate Edition also exists.",p:"WAIT cheap."},
{t:"Hello Neighbor 2",s:"Eerie Guest and tinyBuild's 2022 stealth horror sequel follows journalist Quentin investigating Raven Brooks, sneaking past AI-driven neighbors into locked houses.",w:"It has an interesting open town and adaptive AI that make stealth feel unpredictable.",c:"Confusing puzzles, technical issues and a vague story; the AI can be frustrating.",r:"For Hello Neighbor fans who enjoy the series' odd mystery; others may find it frustrating.",b:"Physical PS4 Blu-ray from Gearbox Publishing, December 2022, with a PS5 upgrade.",p:"WAIT cheap."},
{t:"Truck Racing Championship",s:"N-Racing and Bigben's 2019 truck racing sim covers the FIA European Truck Racing Championship, with heavy trucks, licensed tracks and career management.",w:"It is a rare dedicated truck racing game on PS4, with authentic championship content.",c:"Its narrow focus on heavy trucks, modest presentation and slow-paced racing limit broader appeal.",r:"A niche pick for truck racing fans who want an officially licensed championship simulation.",b:"Physical PS4 Blu-ray from Bigben, 2019, sold in PAL regions as FIA European Truck Racing Championship.",p:"WAIT cheap."},
{t:"The Survivalists",s:"Team17's 2020 survival game from The Escapists team strands players on islands, where they craft, explore and train monkeys to automate tasks.",w:"Its monkey-training system is a fun, unique twist on crafting survival, with online co-op for four.",c:"Repetitive survival tasks and a limited endgame; it is best with friends rather than solo.",r:"A charming co-op survival game for fans of crafting sims who want something lighthearted.",b:"Physical PS4 disc from Team17 with physical distribution by Sold Out, October 2020 (EAN 5056208806826).",p:"MAYBE cheap."},
{t:"Redout 2",s:"34BigThings' 2022 anti-gravity racer offers fast, demanding racing across futuristic tracks, with deep ship customization and a long career.",w:"It is one of the best modern anti-gravity racers, with a strong sense of speed and great track design.",c:"Steep difficulty, complex handling and some PS4 performance limits compared with newer hardware.",r:"A must for fans of WipEout-style racers who want speed, challenge and a long career.",b:"Physical PS4 Deluxe Edition from Saber Interactive, December 2022, including the base game and Season Pass.",p:"BUY cheap."},
{t:"Matchpoint: Tennis Championships",s:"Torus Games and Kalypso's 2022 tennis game offers realistic matches, licensed players and a career mode with rivalries.",w:"It is a solid tennis sim with realistic shot timing, one of the few modern tennis games on PS4.",c:"A small player roster and limited content options, with modest presentation compared with older tennis games.",r:"A good choice for tennis fans looking for a realistic simulation rather than an arcade game.",b:"Physical PS4 copy from Kalypso, sold as the Legends Edition, July 2022.",p:"MAYBE cheap."},
{t:"Severed Steel",s:"Greylock Studio's 2021 first-person shooter stars one-armed Steel, combining slow-motion, wall running, sliding and destructible environments in short, stylish levels.",w:"It is a fast, stylish shooter with movement that rewards creativity, and its destruction makes every room a playground.",c:"A short campaign, thin story and simple structure mean the main draw is replaying levels.",r:"A thrilling, compact action game that respects your time and rewards stylish, creative play.",b:"Physical PS4 release from Merge Games, September 2022, after the July 2021 digital launch.",p:"BUY cheap."},
{t:"Miss Kobayashi's Dragon Maid: Burst Forth!! Choro-gon Breath",s:"Kayac and Aksys's 2022 retro-styled arcade action game based on the Miss Kobayashi's Dragon Maid anime has Tohru and friends battling through short stages.",w:"It is a fan-focused licensed game with charming pixel art and the anime's characters.",c:"Very short with limited content; it is mainly for fans of the series.",r:"Only for Dragon Maid fans who want a light arcade novelty featuring the anime's cast.",b:"Physical PS4 Blu-ray from Aksys Games in North America, August 2022, after the March 2022 Japanese release.",p:"WAIT cheap."},
{t:"RICO London",s:"Ground Shatter's 2021 co-op shooter sends police officers through a procedurally arranged London tower, breaching doors and clearing rooms in slow-motion.",w:"It is a fun, quick co-op shooter with a satisfying breach-and-clear loop.",c:"Repetitive levels and simple enemy AI; the content is short and limited for solo players.",r:"A good co-op action game for friends looking for quick sessions of breach-and-clear shooting.",b:"Physical PS4 Blu-ray from Aksys Games, December 2021, with a European release from Numskull Games.",p:"MAYBE cheap."},
{t:"My Little Pony: A Maretime Bay Adventure",s:"Melbot Studios and Outright Games' 2022 adventure follows Sunny Starscout and friends from My Little Pony: A New Generation, with mini-games and exploration.",w:"It is a gentle, child-friendly game with characters from the 2021 film.",c:"Short, easy and repetitive, with little appeal outside its young fan audience.",r:"A pleasant pick for young My Little Pony fans who loved the 2021 film.",b:"Physical PS4 Blu-ray from Outright Games, May 2022; distinct from A Zephyr Heights Mystery.",p:"WAIT cheap."},
{t:"Matchbox Driving Adventures",s:"Outright Games and Mattel's 2024 open-world driving game lets players drive licensed Matchbox cars through missions, races and rescue tasks.",w:"It is a gentle, accessible driving game for young fans of Matchbox toys.",c:"Simple handling and repetitive missions with very little challenge for older players.",r:"A gentle kids' driving game for young fans of Matchbox cars and toy collections.",b:"Physical PS4 disc from Outright Games, September 2024, listed by The Game Collection as a physical disc.",p:"WAIT cheap."},
{t:"Mickey Storm and the Cursed Mask",s:"Triangle Studios' 2021 3D platform adventure follows sailor Mickey Storm on an island quest to break a mask's curse, with puzzles and combat.",w:"It is a simple, family-friendly 3D platformer with colorful island environments and light puzzle solving.",c:"Basic mechanics, modest presentation and limited challenge for anyone experienced with 3D platformers.",r:"A light family platformer; genre fans can find far better 3D platformers on PS4.",b:"Physical PS4 edition in North America from GS2 Games, December 2021 (UPC 850017102576).",p:"WAIT cheap."},
{t:"DNF Duel",s:"Arc System Works and Eighting's 2022 fighting game adapts the Dungeon & Fighter universe, with an MP-based system and easy special move inputs.",w:"It has excellent visuals and an accessible but flashy combat system that rewards aggression.",c:"Balance problems at launch, a small online community and limited single-player content.",r:"A good anime fighter with plenty of style; not essential for most players outside the genre.",b:"Physical PS4 release from Arc System Works America, June 2022, with a physical-copy pre-order bonus.",p:"MAYBE cheap."},
{t:"Ryan's Rescue Squad",s:"Outright Games and Stage Clear Studios' 2022 platformer is based on the Ryan's World YouTube channel, with Ryan and friends rescuing heroes from villains.",w:"It is a simple platformer for young fans of Ryan's World, with co-op play.",c:"Easy, short and repetitive, with little appeal for older players beyond its young audience.",r:"For young Ryan's World fans only; adults will get almost nothing out of it.",b:"Physical PS4 disc from Outright Games, March 2022; distinct from Race with Ryan.",p:"WAIT cheap."},
{t:"Re:Zero - The Prophecy of the Throne",s:"Chime and Spike Chunsoft's 2021 visual novel and strategy game features an original Re:Zero story by Tappei Nagatsuki, with Subaru using Return by Death to change fate.",w:"It is a must-have for Re:Zero fans, with an original story by the series' author.",c:"Very text heavy, with simple strategy battles; it assumes knowledge of the anime.",r:"For Re:Zero fans who enjoy visual novels and want an original story from the author.",b:"Physical PS4 Day One Edition from Spike Chunsoft, January 2021, with physical-only pins.",p:"WAIT cheap."},
{t:"Train Sim World 3",s:"Dovetail Games' 2022 train sim adds dynamic weather, improved lighting and new routes, continuing the series' detailed rail operations.",w:"Its dynamic weather and lighting make train operations more atmospheric and challenging than earlier entries.",c:"Steep learning curve, much content sold as DLC, and a near-annual release cycle that repeats systems.",r:"A strong sim for rail fans, though annual releases make collecting tricky.",b:"Physical PS4 disc from Dovetail Games with retail by Maximum Games, September 2022.",p:"MAYBE cheap."},
{t:"Monster Harvest",s:"Maple Powered Games' 2021 farming RPG lets players plant slimes to grow monsters, which they can then use in turn-based battles and dungeon exploration.",w:"Its slime-planting system is a creative twist on farming sims, turning crops into battle monsters.",c:"Bugs, shallow systems and a slow progression; it was criticized at launch.",r:"An interesting idea let down by execution; curious genre fans should buy it only cheaply.",b:"Physical PS4 release from Merge Games, September 2021, after several delays to the physical edition.",p:"WAIT cheap."},
{t:"Theatrhythm Final Bar Line",s:"indieszero and Square Enix's 2023 rhythm game celebrates 35 years of Final Fantasy with hundreds of songs from across the series, tapped along to by chibi party members in Series Quests and Music Stages.",w:"It is the biggest Final Fantasy music collection ever put in a game, and the light RPG layer of parties, abilities and summons gives songs extra replay purpose.",c:"Many fan-favorite tracks sit behind paid DLC packs, the chibi presentation is simple, and the higher difficulties demand serious rhythm-game precision.",r:"A joyful, generous celebration for Final Fantasy fans; few games make revisiting a series' soundtrack this much fun in short sessions.",b:"Physical PS4 Standard Edition from Square Enix, February 2023; the Deluxe and Premium Digital Deluxe editions were digital only.",p:"BUY cheap."},
{t:"MONARK",s:"Lancarse and FuRyu's 2022 dark school RPG sends a student through Shin Mikado Academy, where a mysterious Mist has trapped students and Pactbearers fight with demonic Daemons tied to their sins.",w:"Its Ego-based stat system and psychological horror themes give it a distinct identity among school-set JRPGs, with a grim story and tactical turn-based battles.",c:"Long stretches of slow exploration, a bland school setting and a muddled story keep it below the Persona games it clearly evokes.",r:"For dark JRPG fans who enjoy psychological themes and are tolerant of slow pacing and budget presentation.",b:"Physical PS4 Deluxe Edition from NIS America, February 2022 (UPC 810023037637), sold through Target and other retailers.",p:"WAIT cheap."},
{t:"Reel Fishing: Road Trip Adventure",s:"Natsume's 2019 fishing game follows a group of friends on a road trip to fishing spots across the countryside, catching fish, upgrading gear and enjoying light story scenes between trips.",w:"It is an easygoing, approachable fishing game with a friendly road-trip framing that suits relaxed play sessions.",c:"Simple fishing mechanics, limited locations and basic presentation make it repetitive for anyone wanting a fishing simulation.",r:"A gentle, low-stakes pick for players who enjoy casual fishing; serious fishing fans will want something deeper.",b:"Physical PS4 release from Natsume in North America, sold as a US edition and imported by some Brazilian retailers.",p:"WAIT cheap."},
{t:"Slaycation Paradise",s:"Hammer Labs' 2022 top-down arena shooter sends a monster-slaying tourist through holiday-resort-themed arenas, blasting waves of demons with an expanding arsenal.",w:"It has an amusing vacation theme and quick, arcade-style arena combat that suits short play sessions.",c:"Content is light, arenas start to repeat quickly, and the twin-stick shooting lacks the depth of genre leaders.",r:"A fun, cheap distraction for twin-stick shooter fans; there is not much here for long-term play.",b:"Physical retail edition from Merge Games for PlayStation 4, PlayStation 5 and Switch, sold through European retailers.",p:"WAIT cheap."},
{t:"The Smurfs: Mission Vileaf",s:"OSome Studio and Microids' 2021 3D platformer has the Smurfs fighting the Vileaf plants spread by Gargamel, using the Smurfizer backpack to clean infected areas and battle enemies.",w:"It is a pleasant, well-made licensed platformer with colorful worlds and abilities that suit young players and families.",c:"Simple combat, limited challenge and a short campaign mean experienced platformer players will finish it quickly.",r:"A charming family platformer and a better-than-average licensed game for young Smurfs fans.",b:"Physical PS4 Smurftastic Edition from Microids, October 2021, with the game plus extras; the Collector Edition was Switch-only.",p:"MAYBE cheap."},
{t:"The Cruel King and the Great Hero",s:"Nippon Ichi's 2022 picture-book JRPG follows Yuu, a young girl raised by the Dragon King, as she trains to become a hero, in hand-drawn storybook visuals.",w:"Its watercolor art and heartfelt story give it a gentle, unique charm rarely seen in JRPGs.",c:"Very simple turn-based combat, slow pacing and frequent random encounters can wear on experienced players.",r:"A cozy, warm-hearted JRPG for players who value charm and story over challenge.",b:"Physical PS4 release from NIS America, March 2022, including the Storybook Edition; PriceCharting lists one game disc.",p:"MAYBE cheap."},
{t:"Kamiwaza: Way of the Thief",s:"Acquire's 2022 remaster of its 2006 stealth action game casts players as an Edo-period thief who steals from corrupt merchants, chaining thefts into combos and helping the poor.",w:"Its combo-based theft system is an unusual, satisfying twist on stealth games from the team behind Tenchu.",c:"Dated level design, repetitive missions and a short campaign show the game's PS2-era roots.",r:"A fun, rare stealth curio for fans of Edo-era settings and Acquire's style.",b:"Physical PS4 release from NIS America, October 2022; library records describe it as a single PS4 Blu-ray disc.",p:"MAYBE cheap."},
{t:"Evil Genius 2: World Domination",s:"Rebellion's 2021 villain lair sim has players build a secret island base, train minions, run casino fronts and launch schemes against super agents and rival forces of justice.",w:"It is a funny, stylish base-builder that captures the spy-movie villain fantasy with charming 1960s design.",c:"Late-game micromanagement, slow pacing and a fiddly controller interface on console can frustrate players.",r:"A charming management game for fans of base-building who enjoy a playful villain theme.",b:"Physical PS4 release via Game Source Entertainment in Asia, November 2021; Rebellion lists a Standard Physical edition.",p:"MAYBE cheap."},
{t:"Moving Out 2",s:"SMG Studio and Team17's 2023 co-op physics game sends Packmore movers across dimensions, throwing furniture through windows and racing the clock in chaotic levels.",w:"It improves on the original with more creative levels, online co-op and up to four players for hilarious chaos.",c:"Best with friends; solo play is less fun, and some levels become frustrating with precise timing demands.",r:"An excellent party game that respects short play sessions with friends and family.",b:"Physical edition for PS4, PS5 and Switch from Fireshine/Just For Games, sold through Target and European retailers.",p:"BUY cheap."},
{t:"New Joe and Mac Caveman Ninja",s:"Mr. Nutz Studio and Microids' 2022 remake of Data East's 1991 arcade platformer brings Joe and Mac back with hand-drawn visuals and two-player co-op against prehistoric enemies.",w:"It is a faithful, colorful remake of a classic arcade game, with smooth co-op and a bright new art style.",c:"Very short and simple, with arcade-era design that makes it a single-afternoon experience.",r:"A nostalgic co-op romp best played with a friend in short bursts.",b:"Physical PS4 T-Rex Edition from Microids, December 2022, after the November 2022 digital release.",p:"MAYBE cheap."},
{t:"Hotshot Racing",s:"Lucky Mountain Games and Sumo Digital's 2020 arcade racer uses a flat-shaded early-1990s polygon style, with drifting, boost and four-player split-screen racing.",w:"It captures the feel of classic arcade racers like Virtua Racing, with tight drifting and fun local multiplayer.",c:"Limited track count, a simple career and rubber-band AI can make solo play repetitive.",r:"A fast, stylish arcade racer that respects your time and shines in split-screen.",b:"Physical PS4 release in 2021, including a European edition from Just For Games; library records list one Blu-ray disc.",p:"BUY cheap."},
{t:"Clive 'N' Wrench",s:"Dinosaur Bytes' 2023 3D collectathon follows a rabbit and a monkey traveling through time to stop Dr. Daravolt, in the tradition of Banjo-Kazooie.",w:"It is a sincere homage to late-1990s collectathon platformers, with varied worlds and many collectibles.",c:"A rough camera, inconsistent controls and dated visuals make some of the precision platforming frustrating.",r:"A nostalgic pick for collectathon fans who are willing to accept rough edges for the sake of variety.",b:"Physical PS4 Standard and Collector's Edition from Numskull Games, February 2023, sold through UK retailers.",p:"WAIT cheap."},
{t:"MechWarrior 5: Mercenaries",s:"Piranha Games' mech combat game puts players in charge of a mercenary company in the BattleTech universe, piloting and outfitting giant mechs across contracts.",w:"It delivers weighty, satisfying mech combat and a deep mercenary-company management layer, with co-op for four players.",c:"Repetitive missions, weak story and a slow, grindy mid-game; console controls are less precise than PC.",r:"A strong pick for BattleTech fans who enjoy customization and big stompy robots.",b:"Physical PS4 box set from PLAION, released in November for PlayStation and Xbox platforms.",p:"MAYBE cheap."},
{t:"Disgaea 6 Complete",s:"Nippon Ichi's tactical RPG follows Zed, a zombie who uses Super Reincarnation to grow stronger, in a story about defeating the God of Destruction.",w:"It adds auto-battle and level caps in the millions, making the series' extreme grinding more accessible.",c:"The 3D visuals and story are weaker than earlier games, and auto-battle can remove much of the challenge.",r:"A good entry for Disgaea fans who want grinding made easier; tactics purists may prefer older games.",b:"Physical PS4 release from NIS America, June 2022, including the Deluxe Edition; the Complete name is the identity.",p:"MAYBE cheap."},
{t:"My Little Pony: A Zephyr Heights Mystery",s:"Drakhar Studio and Outright Games' 2024 adventure follows Sunny Starscout and friends investigating a mystery in Zephyr Heights, with mini-games and exploration.",w:"It is a child-friendly adventure that improves on the earlier Maretime Bay game with more varied activities.",c:"Easy, short and simple, with little appeal outside the young fans it targets.",r:"A pleasant game for young My Little Pony fans to play with family.",b:"Physical PS4 disc from Outright Games, May 2024 (UPC 819338024295); distinct from A Maretime Bay Adventure.",p:"WAIT cheap."},
{t:"Minecraft Legends",s:"Mojang and Blackbird Interactive's 2023 action strategy spin-off has players rallying Minecraft mobs to defend the Overworld from invading piglins in a procedurally generated world.",w:"It is a fresh spin on Minecraft, combining base building and army command with a charming art style.",c:"Simple strategy, repetitive campaigns and limited long-term support, which ended in early 2024.",r:"A fun, light strategy game for Minecraft fans; strategy veterans may find it shallow.",b:"Physical PS4 Deluxe Edition from Microsoft/Mojang, April 2023, including the game disc plus six in-game skins.",p:"MAYBE cheap."},
{t:"Speed 3 Grand Prix",s:"Lion Castle's 2020 futuristic arcade racer sends sleek vehicles through high-speed circuits with boosts and a simple championship structure, released on a budget price point.",w:"It is a fast, simple arcade racer for players who enjoy futuristic racing on a budget.",c:"Limited content, basic presentation and simple handling; it is far behind leaders like Redout.",r:"A cheap budget racer for fans of anti-gravity racing; Redout 2 is far better.",b:"Physical PS4 release from GS2 Games in North America and Mindscape in Europe, November 2020.",p:"WAIT cheap."},
{t:"Maglam Lord",s:"Felistella and D3 Publisher's 2022 action RPG follows a demon lord who awakens in a world now ruled by humans and must find a partner to preserve the demon race.",w:"It is a humorous, offbeat action RPG with a shape-changing weapon and a romance system with a quirky cast.",c:"Simple combat, repetitive dungeons and low-budget visuals limit its appeal outside fans of quirky JRPGs.",r:"A playful oddity for JRPG fans who enjoy humor and romance mechanics.",b:"Physical PS4 Limited Edition from PQube via Funstock, February 2022; the limited edition is packaging of the same game.",p:"WAIT cheap."},
{t:"Kukoos: Lost Pets",s:"PetitFabrik and Modus Games' 2022 3D platformer follows the Kukoos rescuing lost pets across colorful worlds, with four-player local co-op.",w:"It is a simple, bright co-op platformer that suits young families who want to play together.",c:"Basic level design, simple mechanics and limited challenge; experienced platformer players will finish quickly.",r:"A family co-op pick for young players; better platformers exist for solo play.",b:"Physical PS4 disc from Modus Games, December 2022 (UPC 814290018450), with complete and sealed copies circulating.",p:"WAIT cheap."},
{t:"Skul: The Hero Slayer",s:"SouthPAW Games' 2021 roguelite action platformer follows Skul, a skeleton warrior who swaps skulls to change abilities while fighting the Imperial Army that destroyed the Demon King's castle.",w:"Its skull-swapping system offers huge build variety, and its pixel-art combat is fast and satisfying.",c:"Difficulty spikes, randomness and a long grind for unlocks can frustrate players.",r:"A great, replayable roguelite for players who love fast action and build variety.",b:"Physical PS4 Standard and Signature Edition from Merge Games, April 2022, mostly sold in Europe.",p:"BUY cheap."},
{t:"Turnip Boy Commits Tax Evasion",s:"Snoozy Kazoo's 2021 comedic action adventure follows Turnip Boy through a Zelda-style world after he is caught evading taxes, ripping up documents and solving simple puzzles.",w:"It is a short, funny and charming adventure with clever writing and a lighthearted tone.",c:"Very short with simple combat and puzzles; the humor may not appeal to everyone.",r:"A delightful, brief adventure that respects your time and leaves you smiling.",b:"Physical PS4 release from Graffiti Games, 2023 (UPC 812303019500), after the December 2022 digital launch.",p:"BUY cheap."},
{t:"Winter Games 2023",s:"Wild River's 2022 multi-event winter sports game gathers a range of Olympic-style winter disciplines into a party-friendly competition format for local players.",w:"It offers a range of winter events for local multiplayer that suits casual group play.",c:"Basic presentation and simple events; the year-titled name ties it to an annual sports format.",r:"A light party game for winter sports fans; little depth for solo players.",b:"Physical PS4 Blu-ray from Merge Games, October 2022; a curator should weigh the annual-sports rule.",p:"WAIT cheap."},
{t:"Monster Crown",s:"Studio Aurum's 2021 monster-taming RPG lets players catch and breed monsters into new hybrids, in a darker setting than most creature collectors.",w:"Its deep breeding system creates thousands of monster combinations, offering lots of experimentation.",c:"Rough presentation, confusing progression signposting and an uneven difficulty curve hold back its clever ideas.",r:"A good pick for monster-taming fans who enjoy breeding experiments more than polished story campaigns.",b:"Physical PS4 release from SOEDESCO, February 2022; Target lists it as a physical-format PS4 release.",p:"WAIT cheap."},
{t:"Can't Drive This",s:"Pixel Maniacs' 2021 party game has one player driving a truck that explodes if it slows down while another builds the road ahead in real time.",w:"It is a creative, chaotic co-op game with lots of laughs and simple controls.",c:"Thin solo content and limited variety once you've played the main modes.",r:"A fun party game for friends looking for chaotic, short sessions of shouting and frantic track building.",b:"Physical PS4 release from Perp Games, May 2021, sold at major US retailers after the March 2021 digital launch.",p:"MAYBE cheap."},
{t:"Tin and Kuna",s:"Black River Studios' 2020 3D platformer follows Tin, a creature who rolls in a ball through puzzle-filled worlds to restore balance with the god Kuna.",w:"It is a pleasant puzzle platformer with charming visuals and a simple rolling mechanic.",c:"Short, easy and occasionally imprecise rolling physics, with little reason to replay once the worlds are done.",r:"A light puzzle platformer for families or casual players who want a relaxed, colorful weekend game.",b:"Physical PS4 release from Aksys Games in North America, September 2020 (UPC 853736006903).",p:"WAIT cheap."},
{t:"Super Bullet Break",s:"BeXide and PQube's 2022 deck-building roguelike has players collecting Bullet characters from classic games and using them in card battles to restore a digital world.",w:"It has a fun deck-building system and charming character designs, with a lighthearted, anime-styled story.",c:"Repetitive runs, simple card synergies and a slow start limit long-term appeal.",r:"A good deck-builder for anime fans who enjoy collecting characters and tinkering with card synergies.",b:"Physical PS4 Day One Edition from PQube in Europe, September 2022, with artbook and collector's box.",p:"WAIT cheap."},
{t:"Phoenix Point",s:"Snapshot Games' tactics game from X-COM creator Julian Gollop has players fighting the alien Pandoravirus, with free-aim shooting and factions to manage.",w:"It has deep tactical combat, with free aiming and destructible limbs that add unique choices.",c:"Steep difficulty, repetitive missions and a complex strategy layer; the console port has slow menus.",r:"A rewarding tactics game for X-COM fans who want something deeper and are prepared for difficulty.",b:"Physical PS4 Behemoth Edition from Prime Matter/Koch Media, October 2021, including expansions.",p:"MAYBE cheap."},
{t:"DIRT 5",s:"Codemasters' 2020 arcade off-road racer offers a career narrated by Troy Baker and Nolan North, with rally cross, ice racing and stadium events across the world.",w:"It is a colorful, accessible off-road racer with four-player split-screen and a fun Playgrounds track editor.",c:"Its arcade handling may disappoint rally sim fans, and the PS4 version runs at reduced performance.",r:"A fun, arcade off-road racer for split-screen and casual play, best enjoyed with friends on one couch.",b:"Physical PS4 Blu-ray from Koch Media, November 2020 (UPC 816819017999); launch editions are packaging only.",p:"MAYBE cheap."},
{t:"Moto Racer 4",s:"Artefacts Studio and Microids' 2016 revival of the Moto Racer series offers road and dirt motorcycle racing with arcade handling and stunt boosts.",w:"It is an accessible arcade motorcycle racer with varied tracks, appealing to fans of the original games.",c:"Shallow content, average visuals and twitchy handling; optional VR content is limited.",r:"A nostalgic arcade racer for longtime Moto Racer fans; it is only average for everyone else.",b:"Physical PS4 Standard Edition from Microids, 2016, with boxed retail copies in Europe and the UK.",p:"WAIT cheap."},
{t:"SpongeBob SquarePants: The Patrick Star Game",s:"Purple Lamp and THQ Nordic's 2024 adventure stars Patrick in Bikini Bottom, causing chaos and taking on quirky missions while exploring an open hub.",w:"It is a funny, playful game with the show's voice cast and lots of slapstick humor.",c:"Repetitive missions, simple mechanics and a short campaign keep it from matching The Cosmic Shake.",r:"A light, funny game for SpongeBob fans and families who enjoy Patrick's chaotic brand of humor.",b:"Physical PS4 release from THQ Nordic, October 2024; Target lists it as a physical-format PS4 release.",p:"MAYBE cheap."},
{t:"The Eternal Cylinder",s:"ACE Team's 2021 surreal survival adventure follows Trebhum creatures fleeing a giant rolling cylinder, evolving new bodies and abilities by eating strange food.",w:"It is a strange, imaginative world with a unique evolution system and memorable alien designs.",c:"Repetitive survival tasks, uneven pacing and a long, slow middle section test patience before the payoff.",r:"A creative, one-of-a-kind adventure for players who love strange worlds and unusual creature design.",b:"Physical PS4 release from Good Shepherd, November 2021 (UPC 812303016547), after the September digital launch.",p:"MAYBE cheap."},
{t:"Root Film",s:"Kadokawa's 2021 Western release of the mystery adventure follows filmmaker Rintaro Yagumo investigating murders in Shimane Prefecture, a follow-up to Root Letter.",w:"It is a solid mystery visual novel with multiple cases and a real-world setting in Shimane.",c:"Very text heavy, with simple deduction sequences, slow pacing and long stretches of reading between cases.",r:"A good mystery visual novel for genre fans who enjoy real-world settings and episodic cases.",b:"Physical PS4 Blu-ray from PQube in the West, March 2021, sold through European retailers.",p:"MAYBE cheap."},
{t:"Victor Vran: Overkill Edition",s:"Haemimont Games' 2017 console action RPG follows demon hunter Victor Vran in the city of Zagoravia, including the Motörhead: Through the Ages and Fractured Worlds expansions.",w:"Its acrobatic combat, wall jumps and weapon variety make it a fun alternative to Diablo-style RPGs.",c:"Repetitive environments, a forgettable story and a limited endgame compared with bigger action RPGs.",r:"A solid action RPG for fans looking for something different from Diablo.",b:"Physical PS4 release from Wired Productions, with distribution by THQ Nordic, 2017; later reissued as a Black Label release.",p:"MAYBE cheap."},
{t:"Surviving the Aftermath",s:"Iceflake Studios and Paradox's 2021 post-apocalyptic colony builder has players managing survivors, scavenging resources and defending against disasters.",w:"It has a deep survival management system and a well-realized post-apocalyptic setting.",c:"Slow pacing, a complex console interface and a repetitive late game make long sessions feel heavy.",r:"A good colony builder for strategy fans who want a post-apocalyptic twist on settlement management.",b:"Physical PS4 Day One Edition from Paradox Interactive, 2021, sold as a Blu-ray in MediaMarkt and other stores.",p:"MAYBE cheap."},
{t:"The Legend of Heroes: Trails to Azure",s:"Falcom's 2023 English release of the Crossbell sequel continues the Special Support Section's story, with Lloyd Bannings uncovering a city in political turmoil.",w:"It is one of the most praised Trails games, with a strong story and improved combat over Trails from Zero.",c:"It requires Trails from Zero to understand the story, and the visuals are dated.",r:"A top-tier JRPG for Trails fans; play Trails from Zero first to get the full emotional payoff.",b:"Physical PS4 release from NIS America, March 2023, including a Limited Edition.",p:"STRONG buy."},
{t:"New Tales from the Borderlands",s:"Gearbox Quebec's 2022 narrative adventure follows Anu, Octavio and Fran on Promethea as they face a corporate invasion, with dialogue choices and quick-time events.",w:"It continues the Telltale-style storytelling of Tales from the Borderlands with a new cast and comedic tone.",c:"Weaker writing than the original Tales, minimal gameplay and humor that lands unevenly across episodes.",r:"For Borderlands fans who enjoy narrative games; the original Tales is better.",b:"Physical PS4 Deluxe Edition from 2K, October 2022; the Standard Edition was digital-only.",p:"WAIT cheap."},
{t:"Them's Fightin' Herds",s:"Mane6's 2020 fighting game features hooved animals designed by Lauren Faust, with unique mechanics for each character and rollback netcode.",w:"It is a surprisingly deep, well-made fighter with excellent animation and rollback online play.",c:"Small roster and a niche aesthetic that may not appeal to everyone; story mode is short.",r:"A great fighter for genre fans willing to look past its pony-inspired look.",b:"Physical PS4 Deluxe Edition from Modus Games/Maximum Games, October 2022, including the base game.",p:"MAYBE cheap."},
{t:"Professional Farmer 2017",s:"Visiontrick and UIG Entertainment's 2017 farming sim lets players manage crops, livestock and machinery on a farm, with licensed vehicles.",w:"It is a farming sim alternative to Farming Simulator for players who want simple progression.",c:"Clunky controls, dated visuals and limited depth compared with Farming Simulator in the same era.",r:"For farming sim completionists only; any Farming Simulator release is the better choice for most players.",b:"Physical PS4 release from UIG Entertainment, 2017, sold as Professional Farmer 2017 Gold Edition in North America.",p:"WAIT cheap."},
{t:"The Sisters: Party of the Year",s:"Balio Studio and Microids' 2021 party game based on the French comic Les Sisters has players competing in mini-games to throw the best party.",w:"It is a family-friendly party game with simple mini-games and the comic's characters.",c:"Limited content, simple mini-games and little appeal beyond young fans of the French comic series.",r:"A light family party game for young fans who already love the Sisters comics and cartoon.",b:"Physical PS4 Blu-ray from Microids, mid-2021, with a US copy sold by DataBlitz.",p:"WAIT cheap."},
{t:"Tunic",s:"Andrew Shouldice and Finji's 2022 isometric action adventure follows a small fox in a mysterious land, using in-game manual pages to uncover secrets.",w:"It is a brilliant, secret-filled adventure where discovery is central, with a beautiful art style and clever puzzles.",c:"Challenging combat and deliberately obscure puzzles may frustrate players who want clear guidance and objectives.",r:"A top-tier adventure that rewards curiosity and patience, with secrets worth discovering long after the credits.",b:"Physical PS4 Deluxe Edition from Fangamer, shipped around July 2023, with bonus items.",p:"TOP-TIER buy."},
{t:"NOOB: The Factionless",s:"Olydri Games and Microids' 2023 RPG is based on the French web series Noob, following players inside the online game Horizon, with turn-based combat.",w:"It is a fun, nostalgic RPG for fans of the Noob web series, with comedic writing.",c:"Generic turn-based gameplay and limited appeal for anyone who does not know the web series characters.",r:"For fans of the French Noob web series only; general RPG players will find it unremarkable.",b:"Physical PS4 release from Microids, June 2023, with physical editions in Europe and North America.",p:"WAIT cheap."},
{t:"Monster Menu: The Scavenger's Cookbook",s:"Nippon Ichi's 2023 survival dungeon RPG has players cooking monsters for food to keep their party alive, with hunger, permanent death and tactical battles.",w:"Its survival cooking system is unique, adding tension to every dungeon expedition.",c:"Very demanding, with permanent character loss, strict hunger management and slow, careful dungeon pacing.",r:"A unique, challenging survival RPG for patient players who enjoy punishing resource management.",b:"Physical PS4 Deluxe Edition from NIS America, May 2023, sold as the standard retail disc.",p:"MAYBE cheap."},
{t:"Death or Treat",s:"Saona Studios' 2023 roguelite action platformer follows Scary, a ghost fighting to save Hallow Town from a social-media corporation, with hand-drawn visuals.",w:"Its hand-drawn art and Halloween theme give it a lot of charm, with simple, fun combat.",c:"Repetitive runs, limited enemy and weapon variety, and difficulty spikes in later areas of Hallow Town.",r:"A charming roguelite for Halloween fans who value hand-drawn art over long-term depth.",b:"Physical PS4 disc from Perp Games, 2023 (UPC 812303019999); the PS4 disc followed the PS5 physical, so confirm platform.",p:"WAIT cheap."},
{t:"Days of Doom",s:"SneakyBox and Atari's 2023 post-apocalyptic turn-based tactics roguelite has players leading survivors across a hostile wasteland.",w:"It is a compact tactics roguelite with quick battles suited to short play sessions.",c:"Limited depth, simple battles and repetitive runs mean it runs out of surprises fairly quickly.",r:"A light, inexpensive tactics pick for genre fans who want quick roguelite runs.",b:"Physical PS4 disc from Atari, September 2023, listed by The Game Collection and MediaMarkt.",p:"WAIT cheap."},
{t:"Goodbye World",s:"PM Studios and Flyhigh Works' 2023 narrative puzzle platformer tells the story of two friends who once made games together, mixing personal story with minimal monochrome visuals.",w:"It is a heartfelt, personal story about creativity and friendship, with a distinctive pared-back visual style.",c:"Simple puzzles, short length and a melancholy tone that may not appeal to everyone.",r:"A touching, brief narrative game for players who appreciate personal stories about making games.",b:"Physical PS4 release from PM Studios, June 2023, released alongside PS5 and Switch physical versions.",p:"MAYBE cheap."},
{t:"Process of Elimination",s:"Nippon Ichi's 2023 detective adventure follows Wato Hojo, who joins the Detective Alliance to catch a serial killer, mixing visual novel and tactical investigation.",w:"It is a gripping mystery with a large cast and a unique tactical investigation system.",c:"Long, text-heavy scenes and a slow start mean the strong mystery takes several hours to build.",r:"A great mystery game for visual novel fans who enjoy large casts and twisting deductions.",b:"Physical PS4 Deluxe Edition from NIS America, April 2023, which is the standard retail disc.",p:"MAYBE cheap."},
{t:"Coffee Talk Episode 2: Hibiscus & Butterfly",s:"Toge Productions' 2023 barista visual novel returns to a fantasy Seattle café, where you brew drinks and listen to customers' stories.",w:"It is a relaxing, warm game with lovely music, art and characters.",c:"There is very little gameplay; it is mostly reading, with simple drink-making as the main interaction.",r:"A cozy, comforting game for visual novel fans who want a calm evening with warm characters.",b:"Physical PS4 Single Shot Edition and Collector's Edition from Serenity Forge, 2023.",p:"MAYBE cheap."},
{t:"Disgaea 7: Vows of the Virtueless",s:"Nippon Ichi's 2023 tactics RPG is set in Hinomoto, a Japan-themed Netherworld, following Fuji and Pirilika in a story about honor and bushido.",w:"It is a big improvement over Disgaea 6, with Jumbification, a great setting and deep tactics.",c:"Grind-heavy systems and layers of complex mechanics can overwhelm newcomers to the series.",r:"A top Disgaea entry for tactics fans, and a better starting point than Disgaea 6 for many players.",b:"Physical PS4 Deluxe Edition from NIS America, October 2023, which serves as the standard retail disc.",p:"BUY cheap."},
{t:"Lost Words: Beyond the Page",s:"Sketchbook Games' 2021 narrative platformer follows Izzy's diary and her fantasy story, written by Rhianna Pratchett, with word-based puzzles.",w:"It is a moving story about grief, with clever word puzzles and beautiful art.",c:"Simple platforming and a short length; it is mainly a narrative experience rather than a challenge.",r:"A touching narrative game for story fans, especially those interested in writing and grief.",b:"Physical PS4 release from Limited Run Games, region-free and non-numbered, now sold out at the source.",p:"MAYBE cheap."},
{t:"Disco Elysium: The Final Cut",s:"ZA/UM's 2021 Final Cut of the detective RPG follows an amnesiac detective in Revachol, with full voice acting and political vision quests.",w:"It is one of the best-written RPGs ever made, with extraordinary writing and unique dialogue-based skills.",c:"Text-heavy with little combat; the PS4 version had performance and save issues at launch.",r:"An essential RPG for anyone who values writing, character and player choice over combat.",b:"Physical PS4 disc from Skybound Games, November 2021, with a free PS5 upgrade.",p:"TOP-TIER buy."},
{t:"DREDGE",s:"Black Salt Games' 2023 fishing adventure has players exploring islands by boat, catching fish and uncovering a Lovecraftian mystery.",w:"It is an atmospheric, unique game combining fishing, inventory puzzles and cosmic horror.",c:"It is fairly short, the late game becomes repetitive, and the horror stays mild rather than frightening.",r:"A great indie game for players who love atmosphere, mystery and a satisfying upgrade loop.",b:"Physical PS4 Deluxe Edition from Team17, March 2023, priced and sold alongside PS5 and Xbox Series physical versions.",p:"BUY cheap."},
{t:"Witch on the Holy Night",s:"Type-Moon's 2022 visual novel remaster follows Aoko Aozaki and Alice Kuonji, two witches living in a mansion in a 1980s Japanese town.",w:"It is a stunning visual novel with beautiful art and the origins of Type-Moon's universe.",c:"There is no gameplay beyond reading, and the long, slow story demands patience from new readers.",r:"An essential visual novel for Type-Moon fans and anyone curious about the studio's history.",b:"Physical PS4 Limited Edition from Aniplex, December 2022, sold at Walmart and GameStop.",p:"BUY cheap."},
{t:"Oxenfree",s:"Night School Studio's 2016 supernatural thriller follows Alex and friends on Edwards Island, where a radio opens a ghostly rift.",w:"Its natural, overlapping dialogue system and eerie atmosphere make it a standout narrative game.",c:"Short, with slow walking sections and minimal gameplay beyond conversation and radio tuning.",r:"A great narrative game for players who enjoy dialogue-driven stories and eerie supernatural mysteries.",b:"Physical PS4 release from Limited Run Games, January 2017, after the 2016 digital launch.",p:"BUY cheap."},
{t:"Mercenaries Blaze: Dawn of the Twin Dragons",s:"Rideon's tactical RPG continues the Mercenaries series with grid-based battles and class changes, following twin dragons in a fantasy story.",w:"It is a classic-style tactics game with deep class systems for SRPG fans.",c:"Low-budget presentation, slow pacing and dated menus make it feel like a handheld game from an earlier era.",r:"For fans of classic SRPGs who enjoy class growth and do not mind modest production values.",b:"Physical PS4 release from PM Studios, June 2023 (UPC 850042968055); distinct from Mercenaries Rebirth.",p:"WAIT cheap."},
{t:"Star Trek: Resurgence",s:"Dramatic Labs' 2023 narrative adventure follows Jara Rydek and Carter Diaz aboard the USS Resolute, in a story-driven game from former Telltale developers.",w:"It is a faithful Star Trek story with meaningful choices and strong writing.",c:"Dated animations, stiff character models and limited gameplay sections between dialogue scenes.",r:"A good choice for Star Trek fans who enjoy narrative adventures with meaningful command decisions.",b:"Physical PS4 disc released October 2023 for PS4, PS5 and Xbox, with a free PS5 upgrade from the PS4 copy.",p:"MAYBE cheap."},
{t:"Smurfs Kart",s:"Eden Games and Microids' kart racer features Smurfs characters racing on themed tracks with items and drifting.",w:"It is a polished kart racer for young fans with nice tracks and accessible controls.",c:"A small roster, a limited number of modes and few unlockables keep it from matching genre leaders.",r:"A good family kart racer for young Smurfs fans who want simple, colorful racing with friends.",b:"Physical PS4 disc from Microids, August 2023 (UPC 810066291737), with boxed North American copies following in September.",p:"WAIT cheap."},
{t:"Bugsnax",s:"Young Horses' 2020 adventure sends a journalist to Snaktooth Island to catch Bugsnax, half-bug, half-snack creatures that transform the residents who eat them.",w:"It is a funny, charming game with creative creatures and a surprisingly emotional story.",c:"It is fairly short, and the creature-catching puzzles become repetitive once you learn the main tools.",r:"A delightful, weird adventure worth owning for its creativity and surprisingly heartfelt characters.",b:"Physical PS4 disc sold through Fangamer in early 2021 and later at wider retail, after the 2020 digital launch.",p:"BUY cheap."},
{t:"MADiSON",s:"Bloodious Games' 2022 first-person horror game follows Luca, who uses an instant camera to solve puzzles in a haunted house.",w:"It is a frightening first-person horror game with clever puzzles built around developing instant camera photos.",c:"Obscure puzzles, backtracking and pacing issues can stall progress during the middle of the story.",r:"A strong horror pick for genre fans who want genuine scares and old-school puzzle design.",b:"Physical PS4 Possessed Edition from Perp Games, July 2022, with a book, cards, photos and DLC.",p:"MAYBE cheap."},
{t:"Let's Build a Zoo",s:"Springloaded's 2021 pixel-art zoo management game lets players build zoos, care for animals and splice their DNA into strange hybrids.",w:"Its DNA splicing and moral choices make it a fun, quirky management game.",c:"The late game becomes repetitive, and the cluttered interface is awkward to navigate on a controller.",r:"A charming management game for sim fans who enjoy a quirky, morally flexible take on zoo building.",b:"Physical PS4 disc from Merge Games, September 2022; some physical releases bundle the Dinosaur Island DLC.",p:"MAYBE cheap."},
{t:"OlliOlli2: Welcome to Olliwood",s:"Roll7's 2015 2D skateboarding game sends players through movie-themed Olliwood levels, landing tricks and grinds with precise timing.",w:"It is a tight, addictive arcade skating game with great flow and score attack.",c:"Very challenging timing and a steep learning curve can frustrate players who expect a relaxed skating game.",r:"A must for fans of arcade skating games who enjoy mastering tight, score-attack level design.",b:"Qualifies through the physical OlliOlli: Epic Combo Edition disc, which includes OlliOlli and OlliOlli2.",p:"BUY cheap."},
{t:"Horse Tales Emerald Valley Ranch",s:"Microids' 2022 open-world horse-riding adventure sends the player to Emerald Valley to help save a family ranch, caring for and training horses while exploring the countryside on horseback.",w:"It is one of the more ambitious horse games on PS4, with a sizeable open valley to ride across, horse care and grooming, and races alongside the ranch story.",c:"Simple quest design, repetitive chores and modest presentation; it is aimed at younger players and casual riders rather than anyone wanting a deep simulation.",r:"A gentle, wholesome pick for young horse lovers; players who are not drawn to the theme will find little else to hold them.",b:"Physical PS4 Limited Edition from Microids, November 2022 (UPC 850024479500), containing the standard game plus postcards and stickers.",p:"WAIT cheap."},
{t:"Horse Club Adventures",s:"Wild River Games' 2021 adventure based on Schleich's Horse Club toy line lets players ride and care for horses around Lakeside with the Horse Club friends, completing quests and races.",w:"It is a faithful, child-friendly adaptation of the Schleich Horse Club brand, with a calm open area to ride through and simple horse-care routines.",c:"Very easy and repetitive, with basic visuals and little challenge; adults playing alone will exhaust it quickly.",r:"A pleasant licensed game for young fans of the Horse Club toys; the sequel offers a little more to do.",b:"Physical PS4 disc distributed in North America via Target (UPC 819335021037) and in PAL regions from May 2021.",p:"WAIT cheap."},
{t:"Horse Club Adventures 2: Hazelwood",s:"The 2022 sequel to Horse Club Adventures moves the Schleich Horse Club friends to Hazelwood, with more horses to ride, care for and train across a new countryside setting.",w:"It expands the first game with a new area, more activities and more horses, keeping the gentle tone that suits young players.",c:"Still simple and repetitive, with limited challenge and modest presentation typical of licensed children's games.",r:"The better of the two Horse Club games for young fans who want a calm riding adventure.",b:"Physical PS4 release as Horse Club Adventures 2: Hazelwood Stories from Wild River and Merge Games, November 2022 (US SKU 0819335021532).",p:"WAIT cheap."},
{t:"DreamWorks Spirit Lucky's Big Adventure",s:"Outright Games' 2021 adventure based on the Spirit Untamed film follows Lucky and her horse Spirit around Miradero, with riding, races, mini-games and friends Pru and Abigail.",w:"It is a gentle, film-faithful riding adventure for young fans, with an open town to explore and local co-op for a second player.",c:"Simple activities, repetitive races and a short main story; there is little challenge for older players.",r:"A friendly family pick for children who loved the film; others will find it slight.",b:"Physical PS4 Blu-ray from Outright Games, 2021; library records list one disc under the DreamWorks Spirit Lucky's Big Adventure title.",p:"WAIT cheap."},
];
